package de.terrestris.shoguncore.security;

import de.terrestris.shoguncore.dao.UserDao;
import de.terrestris.shoguncore.model.Role;
import de.terrestris.shoguncore.model.User;
import de.terrestris.shoguncore.model.UserGroup;
import org.apache.commons.lang3.StringUtils;
import org.apache.logging.log4j.Logger;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.authentication.AuthenticationProvider;
import org.springframework.security.authentication.BadCredentialsException;
import org.springframework.security.authentication.DisabledException;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.AuthenticationException;
import org.springframework.security.core.GrantedAuthority;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.userdetails.UsernameNotFoundException;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.transaction.annotation.Transactional;

import java.util.HashSet;
import java.util.Set;

import static org.apache.logging.log4j.LogManager.getLogger;

/**
 * @author Nils Bühner
 */
public class ShogunCoreAuthenticationProvider implements AuthenticationProvider {

    /**
     * The Logger
     */
    private static final Logger LOG = getLogger(ShogunCoreAuthenticationProvider.class);

    @Autowired
    private UserDao<User> userDao;

    @Autowired
    private PasswordEncoder passwordEncoder;

    /**
     * This method has to be {@link Transactional} to allow that associated entities
     * can be fetched lazily.
     *
     * @see org.springframework.security.authentication.AuthenticationProvider#authenticate(org.springframework.security.core.Authentication)
     */
    @Override
    @Transactional(value = "transactionManager", readOnly = true)
    public Authentication authenticate(Authentication authentication)
        throws AuthenticationException {

        // prepare an exception
        final String exceptionMessage = "User and password do not match.";

        // get username/password
        String accountName = authentication.getName();
        String rawPassword = (String) authentication.getCredentials();

        LOG.debug("Trying to authenticate User '" + accountName + "'");

        User user = userDao.findByAccountName(accountName);

        // prepare set of authorities
        Set<GrantedAuthority> grantedAuthorities = new HashSet<GrantedAuthority>();

        String encryptedPassword = null;

        if (user == null) {
            LOG.warn("No user for account name '" + accountName + "' could be found.");
            throw new UsernameNotFoundException(exceptionMessage);
        } else if (!user.isActive()) {
            LOG.warn("The user with the account name '" + accountName + "' is not active.");
            throw new DisabledException(exceptionMessage);
        } else {

            encryptedPassword = user.getPassword();

            // check if rawPassword matches the hash from db
            if (passwordEncoder.matches(rawPassword, encryptedPassword)) {

                Set<Role> allUserRoles = getAllUserRoles(user);

                // create granted authorities for the security context
                for (Role role : allUserRoles) {
                    grantedAuthorities.add(new SimpleGrantedAuthority(role.getName()));
                }

            } else {
                LOG.warn("The given password for user '" + accountName + "' does not match.");
                throw new BadCredentialsException(exceptionMessage);
            }

        }

        // Create corresponding token to forward in Spring Security's filter
        // chain. We will use the SHOGun-Core user as the principal.
        Authentication authResult = null;
        if (grantedAuthorities.isEmpty()) {
            // if the user has no authorities, we will build the
            // UsernamePasswordAuthenticationToken without authorities, which
            // leads to an unauthenticated user, i.e. isAuthenticated() of
            // authenticationToken will return false afterwards.
            LOG.warn("The user '" + accountName + "' has no authorities and will thereby NOT be authenticated.");
            authResult = new UsernamePasswordAuthenticationToken(user, encryptedPassword);
        } else {
            // if we pass some grantedAuthorities, isAuthenticated() of
            // authenticationToken will return true afterwards
            authResult = new UsernamePasswordAuthenticationToken(user, encryptedPassword, grantedAuthorities);

            LOG.debug("The user '" + accountName
                + "' got the following (explicit) roles: "
                + StringUtils.join(getRawRoleNames(grantedAuthorities), ", "));
        }

        final boolean isAuthenticated = authResult.isAuthenticated();
        final String authLog = isAuthenticated ? "has succesfully" : "has NOT";
        LOG.info("The user '" + accountName + "' " + authLog + " been authenticated.");

        return authResult;
    }

    /**
     * @see org.springframework.security.authentication.AuthenticationProvider#supports
     * (java.lang.Class)
     */
    @Override
    public boolean supports(Class<?> authentication) {
        return (UsernamePasswordAuthenticationToken.class
            .isAssignableFrom(authentication));
    }

    /**
     * @param user
     * @return
     */
    private Set<Role> getAllUserRoles(User user) {
        Set<Role> allUserRoles = new HashSet<Role>();

        // user roles
        if (user != null) {
            allUserRoles.addAll(user.getRoles());
        } else {
            return allUserRoles;
        }

        Set<UserGroup> userGroups = user.getUserGroups();
        // userGroup roles
        if (userGroups != null) {
            for (UserGroup userGroup : userGroups) {
                allUserRoles.addAll(userGroup.getRoles());
            }
        }
        return allUserRoles;
    }

    /**
     * @param grantedAuthorities
     * @return
     */
    private Set<String> getRawRoleNames(Set<GrantedAuthority> grantedAuthorities) {
        Set<String> grantedRoles = new HashSet<String>();
        for (GrantedAuthority auth : grantedAuthorities) {
            grantedRoles.add(auth.getAuthority());
        }
        return grantedRoles;
    }

    /**
     * @return the passwordEncoder
     */
    public PasswordEncoder getPasswordEncoder() {
        return passwordEncoder;
    }

    /**
     * @param passwordEncoder the passwordEncoder to set
     */
    public void setPasswordEncoder(PasswordEncoder passwordEncoder) {
        this.passwordEncoder = passwordEncoder;
    }
}
package de.terrestris.shoguncore.security.access;

import de.terrestris.shoguncore.dao.GenericHibernateDao;
import de.terrestris.shoguncore.dao.UserDao;
import de.terrestris.shoguncore.model.PersistentObject;
import de.terrestris.shoguncore.model.User;
import de.terrestris.shoguncore.model.security.Permission;
import de.terrestris.shoguncore.security.access.entity.PersistentObjectPermissionEvaluator;
import de.terrestris.shoguncore.security.access.factory.EntityPermissionEvaluatorFactory;
import org.apache.logging.log4j.Logger;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.context.ApplicationContext;
import org.springframework.security.access.PermissionEvaluator;
import org.springframework.security.core.Authentication;

import java.io.Serializable;
import java.util.Collection;

import static org.apache.logging.log4j.LogManager.getLogger;

/**
 * @author Nils Bühner
 */
public class ShogunCorePermissionEvaluator implements PermissionEvaluator {

    /**
     * The LOGGER instance
     */
    private static final Logger logger = getLogger(ShogunCorePermissionEvaluator.class);

    @Autowired
    private ApplicationContext appContext;

    /**
     * We have to use the DAO here. If we would use the service, we would end
     * with StackOverflow errors as a call to (secured) service methods triggers
     * this PermissionEvaluator class.
     */
    @Autowired
    @Qualifier("userDao")
    private UserDao<User> userDao;

    /**
     * If set to true, the plain principal object from the spring security
     * context will be used as "user". Otherwise the "full" user object will be
     * loaded from the SHOGun-Core database.
     * <p>
     * It may be helpful to set this to true, if the user/principal object from
     * the security context contains information that is not persisted in the
     * database.
     * <p>
     * Setting this to the null value is the same as using "false".
     */
    private Boolean usePlainPrincipal = false;

    /**
     *
     */
    @SuppressWarnings("rawtypes")
    private EntityPermissionEvaluatorFactory permissionEvaluatorFactory;

    /**
     *
     */
    @SuppressWarnings({"rawtypes", "unchecked"})
    @Override
    public boolean hasPermission(Authentication authentication,
                                 Object targetDomainObject, Object permissionObject) {

        boolean hasPermission = false;

        if (authentication != null
            && targetDomainObject != null
            && targetDomainObject instanceof PersistentObject
            && permissionObject instanceof String) {

            User user = null;

            final Object principalObject = authentication.getPrincipal();

            if (principalObject instanceof User) {
                final User principal = (User) principalObject;

                if (usePlainPrincipal) {
                    user = principal;
                } else {
                    // get the "full" user from the database
                    user = userDao.findById(principal.getId());
                }
            }

            final PersistentObject persistentObject = (PersistentObject) targetDomainObject;
            final Integer objectId = persistentObject.getId();
            final String simpleClassName = targetDomainObject.getClass().getSimpleName();
            final Permission permission = Permission.fromString((String) permissionObject);

            String accountName = (user == null) ? "ANONYMOUS" : user.getAccountName();

            logger.trace("Evaluating whether user '" + accountName
                + "' has permission '" + permission + "' on '"
                + simpleClassName + "' with ID " + objectId);

            PersistentObjectPermissionEvaluator entityPermissionEvaluator = permissionEvaluatorFactory
                .getEntityPermissionEvaluator(persistentObject.getClass());

            hasPermission = entityPermissionEvaluator.hasPermission(user, persistentObject, permission);

        } else {
            logger.error("Permission evaluation has been aborted.");
        }

        return hasPermission;
    }

    /**
     *
     */
    @SuppressWarnings({"rawtypes", "unchecked"})
    @Override
    public boolean hasPermission(Authentication authentication,
                                 Serializable targetId, String targetType, Object permission) {

        Class<?> entityClass;

        try {
            entityClass = Class.forName(targetType);
        } catch (ClassNotFoundException e) {
            logger.error("Could not create class for type: " + targetType + "(" + e.getMessage() + ")");
            return false;
        }

        // get all available DAOs from the app context
        Collection<GenericHibernateDao> allDaos = appContext.getBeansOfType(GenericHibernateDao.class).values();

        // the DAO we'll use to get the entity from the database
        GenericHibernateDao daoToUse = null;

        // we'll first try to find the exact matching DAO
        for (GenericHibernateDao dao : allDaos) {
            if (dao.getEntityClass().equals(entityClass)) {
                // we found a matching DAO
                daoToUse = dao;
                logger.debug("Found an exactly matching DAO for type " + entityClass);
                break;
            }
        }

        // if we could not find an exact match, we'll try to use the "next best"
        // from the entity hierarchy
        if (daoToUse == null) {
            for (GenericHibernateDao dao : allDaos) {
                if (dao.getEntityClass().isAssignableFrom(entityClass)) {
                    // we found a DAO that will work (e.g. PersonDao for User.class)
                    daoToUse = dao;
                    logger.debug("Found a matching DAO from the hierarchy of type " + entityClass);
                    break;
                }
            }
        }

        // LOG warning if we could NOT find a matching DAO
        if (daoToUse == null) {
            logger.warn("Could not find a DAO for type:" + entityClass);
            return false;
        }

        // finally get the entity from the DB
        PersistentObject entity = daoToUse.findById(targetId);

        // call implementation based on entity
        return this.hasPermission(authentication, entity, permission);
    }

    /**
     * @return the appContext
     */
    public ApplicationContext getAppContext() {
        return appContext;
    }

    /**
     * @param appContext the appContext to set
     */
    public void setAppContext(ApplicationContext appContext) {
        this.appContext = appContext;
    }

    /**
     * @return the userDao
     */
    public UserDao<User> getUserDao() {
        return userDao;
    }

    /**
     * @param userDao the userDao to set
     */
    public void setUserDao(UserDao<User> userDao) {
        this.userDao = userDao;
    }

    /**
     * @return the usePlainPrincipal
     */
    public Boolean getUsePlainPrincipal() {
        return usePlainPrincipal;
    }

    /**
     * @param usePlainPrincipal the usePlainPrincipal to set
     */
    public void setUsePlainPrincipal(Boolean usePlainPrincipal) {
        this.usePlainPrincipal = usePlainPrincipal;
    }

    /**
     * @return the permissionEvaluatorFactory
     */
    @SuppressWarnings("rawtypes")
    public EntityPermissionEvaluatorFactory getPermissionEvaluatorFactory() {
        return permissionEvaluatorFactory;
    }

    /**
     * @param permissionEvaluatorFactory the permissionEvaluatorFactory to set
     */
    @SuppressWarnings("rawtypes")
    public void setPermissionEvaluatorFactory(
        EntityPermissionEvaluatorFactory permissionEvaluatorFactory) {
        this.permissionEvaluatorFactory = permissionEvaluatorFactory;
    }

}
