//! JSON value model, strict parser and a Jackson-compatible writer
//! (Java `Double.toString` number formatting, Jackson string escaping).

use std::fmt::Write as _;

#[derive(Debug, Clone, PartialEq)]
pub enum JVal {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Arr(Vec<JVal>),
    Obj(Vec<(String, JVal)>),
}

impl JVal {
    pub fn get(&self, key: &str) -> Option<&JVal> {
        match self {
            JVal::Obj(m) => m.iter().rev().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }

    pub fn is_null(&self) -> bool {
        matches!(self, JVal::Null)
    }

    /// Java-style `asInt()` semantics for the `id` check in PUT bodies.
    pub fn as_java_int(&self) -> Option<i64> {
        match self {
            JVal::Int(i) => Some(*i),
            JVal::Float(f) => Some(*f as i64),
            JVal::Str(s) => s.trim().parse::<i64>().ok().or_else(|| s.trim().parse::<f64>().ok().map(|f| f as i64)),
            _ => None,
        }
    }
}

// ---------------------------------------------------------------- parser

pub struct ParseErr;

struct Parser<'a> {
    b: &'a [u8],
    i: usize,
}

pub fn parse(input: &[u8]) -> Result<JVal, ParseErr> {
    let mut p = Parser { b: input, i: 0 };
    p.ws();
    let v = p.value()?;
    p.ws();
    if p.i != p.b.len() {
        return Err(ParseErr);
    }
    Ok(v)
}

impl<'a> Parser<'a> {
    fn ws(&mut self) {
        while self.i < self.b.len() {
            match self.b[self.i] {
                b' ' | b'\t' | b'\n' | b'\r' => self.i += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        self.b.get(self.i).copied()
    }

    fn value(&mut self) -> Result<JVal, ParseErr> {
        match self.peek() {
            Some(b'{') => self.object(),
            Some(b'[') => self.array(),
            Some(b'"') => Ok(JVal::Str(self.string()?)),
            Some(b't') => self.lit(b"true", JVal::Bool(true)),
            Some(b'f') => self.lit(b"false", JVal::Bool(false)),
            Some(b'n') => self.lit(b"null", JVal::Null),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.number(),
            _ => Err(ParseErr),
        }
    }

    fn lit(&mut self, s: &[u8], v: JVal) -> Result<JVal, ParseErr> {
        if self.b.len() - self.i >= s.len() && &self.b[self.i..self.i + s.len()] == s {
            self.i += s.len();
            Ok(v)
        } else {
            Err(ParseErr)
        }
    }

    fn object(&mut self) -> Result<JVal, ParseErr> {
        self.i += 1; // {
        let mut out: Vec<(String, JVal)> = Vec::new();
        self.ws();
        if self.peek() == Some(b'}') {
            self.i += 1;
            return Ok(JVal::Obj(out));
        }
        loop {
            self.ws();
            if self.peek() != Some(b'"') {
                return Err(ParseErr);
            }
            let k = self.string()?;
            self.ws();
            if self.peek() != Some(b':') {
                return Err(ParseErr);
            }
            self.i += 1;
            self.ws();
            let v = self.value()?;
            // last duplicate key wins
            if let Some(slot) = out.iter_mut().find(|(k2, _)| *k2 == k) {
                slot.1 = v;
            } else {
                out.push((k, v));
            }
            self.ws();
            match self.peek() {
                Some(b',') => {
                    self.i += 1;
                }
                Some(b'}') => {
                    self.i += 1;
                    return Ok(JVal::Obj(out));
                }
                _ => return Err(ParseErr),
            }
        }
    }

    fn array(&mut self) -> Result<JVal, ParseErr> {
        self.i += 1; // [
        let mut out = Vec::new();
        self.ws();
        if self.peek() == Some(b']') {
            self.i += 1;
            return Ok(JVal::Arr(out));
        }
        loop {
            self.ws();
            let v = self.value()?;
            out.push(v);
            self.ws();
            match self.peek() {
                Some(b',') => {
                    self.i += 1;
                }
                Some(b']') => {
                    self.i += 1;
                    return Ok(JVal::Arr(out));
                }
                _ => return Err(ParseErr),
            }
        }
    }

    fn string(&mut self) -> Result<String, ParseErr> {
        self.i += 1; // opening quote
        let mut out = String::new();
        loop {
            let c = self.peek().ok_or(ParseErr)?;
            self.i += 1;
            match c {
                b'"' => return Ok(out),
                b'\\' => {
                    let e = self.peek().ok_or(ParseErr)?;
                    self.i += 1;
                    match e {
                        b'"' => out.push('"'),
                        b'\\' => out.push('\\'),
                        b'/' => out.push('/'),
                        b'b' => out.push('\u{8}'),
                        b'f' => out.push('\u{c}'),
                        b'n' => out.push('\n'),
                        b'r' => out.push('\r'),
                        b't' => out.push('\t'),
                        b'u' => {
                            if self.i + 4 > self.b.len() {
                                return Err(ParseErr);
                            }
                            let hex = std::str::from_utf8(&self.b[self.i..self.i + 4]).map_err(|_| ParseErr)?;
                            let cp = u32::from_str_radix(hex, 16).map_err(|_| ParseErr)?;
                            self.i += 4;
                            // handle surrogate pairs like Jackson
                            if (0xD800..0xDC00).contains(&cp) {
                                if self.b.get(self.i) == Some(&b'\\') && self.b.get(self.i + 1) == Some(&b'u')
                                    && self.i + 6 <= self.b.len()
                                {
                                    let hex2 = std::str::from_utf8(&self.b[self.i + 2..self.i + 6]).map_err(|_| ParseErr)?;
                                    let lo = u32::from_str_radix(hex2, 16).map_err(|_| ParseErr)?;
                                    if (0xDC00..0xE000).contains(&lo) {
                                        self.i += 6;
                                        let c = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                        out.push(char::from_u32(c).ok_or(ParseErr)?);
                                        continue;
                                    }
                                }
                                out.push('\u{FFFD}');
                            } else if (0xDC00..0xE000).contains(&cp) {
                                out.push('\u{FFFD}');
                            } else {
                                out.push(char::from_u32(cp).ok_or(ParseErr)?);
                            }
                        }
                        _ => return Err(ParseErr),
                    }
                }
                _ if c < 0x20 => return Err(ParseErr),
                _ => {
                    // collect UTF-8 sequence
                    let start = self.i - 1;
                    let len = utf8_len(c);
                    let end = start + len;
                    if end > self.b.len() {
                        return Err(ParseErr);
                    }
