            _ => Err(ParseErr),
        }
    }

    fn lit(&mut self, s: &[u8], v: JVal) -> Result<JVal, ParseErr> {
        if self.b.len() - self.i >= s.len() && &self.b[self.i..self.i + s.len()] == s {
            self.i += s.len();
            Ok(v)
        } else {
            Err(ParseErr)
        }
    }

    fn object(&mut self) -> Result<JVal, ParseErr> {
        self.i += 1; // {
        let mut out: Vec<(String, JVal)> = Vec::new();
