//! Codec for the Java-serialization format that Hibernate uses to persist
//! the XYZ layer datasource `resolutions` element collection
//! (each row is one `java.io.ObjectOutputStream`-serialized `java.lang.Double`).

/// `ObjectOutputStream` stream header + TC_OBJECT + class descriptors for
/// `java.lang.Double` (extends `java.lang.Number`) declaring the double
/// field `value`. 60 bytes, followed by the 8-byte big-endian double.
const DOUBLE_PREFIX: &[u8] = &[
    0xAC, 0xED, 0x00, 0x05, // stream magic + version
    0x73, // TC_OBJECT
    0x72, // TC_CLASSDESC
    0x00, 0x10, // name length 16
    b'j', b'a', b'v', b'a', b'.', b'l', b'a', b'n', b'g', b'.', b'D', b'o', b'u', b'b', b'l', b'e',
    0x80, 0xB3, 0xC2, 0x4A, 0x29, 0x6B, 0xFB, 0x04, // serialVersionUID of java.lang.Double
    0x02, // flags = java.io.Serializable
    0x00, 0x01, // 1 declared field
    b'D', 0x00, 0x05, b'v', b'a', b'l', b'u', b'e', // double value
    0x78, // TC_ENDBLOCKDATA
    0x72, // superclass TC_CLASSDESC
    0x00, 0x10, // name length 16
    b'j', b'a', b'v', b'a', b'.', b'l', b'a', b'n', b'g', b'.', b'N', b'u', b'm', b'b', b'e', b'r',
    0x86, 0xAC, 0x95, 0x1D, 0x0B, 0x94, 0xE0, 0x8B, // serialVersionUID of java.lang.Number
    0x02, // flags
    0x00, 0x00, // no fields
    0x78, // TC_ENDBLOCKDATA
    0x70, // TC_NULL (Number extends Object)
];

/// TC_NULL: how `writeObject(null)` serializes a null element.
const NULL_VALUE: &[u8] = &[0x70];

pub fn encode_double(d: f64) -> Vec<u8> {
    let mut out = Vec::with_capacity(DOUBLE_PREFIX.len() + 8);
    out.extend_from_slice(DOUBLE_PREFIX);
    out.extend_from_slice(&d.to_bits().to_be_bytes());
    out
}

pub fn encode_null() -> Vec<u8> {
    NULL_VALUE.to_vec()
}

/// Decode a persisted resolution value. `Ok(None)` for a null element,
/// `Err(())` when the bytes are not a readable Java-serialized double
/// (the original fails to deserialize such rows as well).
pub fn decode_value(bytes: &[u8]) -> Result<Option<f64>, ()> {
    if bytes == NULL_VALUE {
        return Ok(None);
    }
    if bytes.len() == DOUBLE_PREFIX.len() + 8 && bytes[..DOUBLE_PREFIX.len()] == *DOUBLE_PREFIX {
        let mut v = [0u8; 8];
