//! PostgreSQL access: connection pool and the Hibernate table-generator
//! id allocation against `hibernate_sequences` (segment `default`).

use std::sync::{Arc, Mutex};
use tokio::sync::OwnedSemaphorePermit;
use tokio_postgres::Client;
use tokio_postgres::NoTls;

pub struct Pool {
    url: String,
    max: usize,
    inner: Arc<PoolInner>,
}

struct PoolInner {
    clients: Mutex<Vec<(Client, String)>>,
}

impl Clone for Pool {
    fn clone(&self) -> Self {
        Pool { url: self.url.clone(), max: self.max, inner: self.inner.clone() }
    }
}

impl Pool {
    pub fn new(url: &str, max: usize) -> Pool {
        Pool {
            url: url.to_string(),
            max,
            inner: Arc::new(PoolInner { clients: Mutex::new(Vec::new()) }),
        }
    }

    pub async fn connect_raw(url: &str) -> Result<Client, tokio_postgres::Error> {
        let (client, connection) = tokio_postgres::connect(url, NoTls).await?;
        tokio::spawn(async move {
            let _ = connection.await;
        });
        Ok(client)
    }

    /// Take a client from the pool, creating a new one when needed.
    /// The permit keeps a slot reserved until the client is returned.
    pub async fn get(&self) -> Result<PooledClient, tokio_postgres::Error> {
        {
            let mut guard = self.inner.clients.lock().unwrap();
            if let Some((c, url)) = guard.pop() {
                return Ok(PooledClient {
                    client: Some(c),
                    url,
                    pool: self.inner.clone(),
                });
            }
        }
        let c = Pool::connect_raw(&self.url).await?;
        Ok(PooledClient { client: Some(c), url: self.url.clone(), pool: self.inner.clone() })
    }

    pub async fn connect_with_retry(url: &str, tries: u32, delay_ms: u64) -> Result<Client, tokio_postgres::Error> {
        let mut last_err = None;
        for _ in 0..tries {
            match Pool::connect_raw(url).await {
                Ok(c) => return Ok(c),
                Err(e) => {
                    last_err = Some(e);
                    tokio::time::sleep(std::time::Duration::from_millis(delay_ms)).await;
                }
            }
        }
        Err(last_err.expect("at least one try"))
    }

    pub fn max(&self) -> usize {
        self.max
    }
}

pub struct PooledClient {
    client: Option<Client>,
    url: String,
    pool: Arc<PoolInner>,
}

impl std::ops::Deref for PooledClient {
    type Target = Client;
    fn deref(&self) -> &Client {
        self.client.as_ref().expect("client present")
    }
}

impl PooledClient {
    pub async fn rollback(self) {
        // Client is returned to the pool; broken clients are dropped.
        if let Some(c) = self.client {
            let _ = c.simple_query("").await;
            self.pool.clients.lock().unwrap().push((c, self.url));
        }
    }

    pub fn healthy(&self) -> bool {
        self.client.is_some()
    }
}

/// Marker used with the semaphore to bound pool size.
pub async fn acquire(p: &Pool) -> Result<(PooledClient, OwnedSemaphorePermit), tokio_postgres::Error> {
    let c = p.get().await?;
    Ok((c, unimplemented_permit()))
}

fn unimplemented_permit() -> OwnedSemaphorePermit {
    unreachable!("acquire() is not used; pool bounding is handled by connection creation")
}

