input.content:
//! Entity model of the ported REST slice: User, UserGroup, Role, Layer,
//! LayerDataSource (+ subtypes), LayerAppearance, Extent, TileGrid.
//!
//! Every struct mirrors the Java entity field-for-field, including the
//! field defaults produced by the Java no-argument constructors (relevant
//! for `output:only` restricted projections and for JSON deserialization).

use crate::javaser;
use crate::json::{java_double, write_str, JVal};

#[derive(Debug, Clone, Default)]
pub struct Role {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub description: Option<String>,
}

#[derive(Debug, Clone)]
pub struct User {
    pub id: Option<i32>,
    pub first_name: Option<String>,
    pub last_name: Option<String>,
    pub email: Option<String>,
    /// ISO date string (YYYY-MM-DD), as joda-time prints it.
    pub birthday: Option<String>,
    pub language: Option<String>,
    pub account_name: Option<String>,
    pub password: Option<String>,
    pub active: bool,
    /// `None` represents a JSON `null` collection.
    pub roles: Option<Vec<Role>>,
    pub user_groups: Option<Vec<i32>>,
}

impl Default for User {
    fn default() -> Self {
        // Java field initializers: `roles = new HashSet<>()`, `userGroups = new HashSet<>()`
        User {
            id: None,
            first_name: None,
            last_name: None,
            email: None,
            birthday: None,
            language: None,
            account_name: None,
            password: None,
            active: false,
            roles: Some(Vec::new()),
            user_groups: Some(Vec::new()),
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct UserGroup {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub owner: Option<Box<User>>,
    pub members: Option<Vec<User>>,
    pub roles: Option<Vec<Role>>,
}

#[derive(Debug, Clone, Default)]
pub struct Extent {
    pub id: Option<i32>,
    pub lower_left: Option<(f64, f64)>,
    pub upper_right: Option<(f64, f64)>,
}

#[derive(Debug, Clone)]
pub struct TileGrid {
    pub id: Option<i32>,
    pub typ: Option<String>,
    pub origin: Option<(f64, f64)>,
    pub extent: Option<Box<Extent>>,
    /// Java constructor default is 256.
    pub tile_size: Option<i32>,
    pub resolutions: Option<Vec<f64>>,
    /// Only present for WmtsTileGrid.
    pub matrix_ids: Option<Vec<String>>,
    pub is_wmts: bool,
}

impl Default for TileGrid {
    fn default() -> Self {
        // Java no-arg TileGrid constructor: `tileSize = Integer.valueOf(256)`.
        TileGrid {
            id: None,
            typ: None,
            origin: None,
            extent: None,
            tile_size: Some(256),
            resolutions: None,
            matrix_ids: None,
            is_wmts: false,
        }
    }
}

impl TileGrid {
    pub fn new_wmts_default() -> TileGrid {
        let mut tg = TileGrid::default();
        tg.is_wmts = true;
        tg
    }
}

#[derive(Debug, Clone, Default)]
pub struct LayerAppearance {
    pub id: Option<i32>,
    pub attribution: Option<String>,
    pub hoverable: Option<bool>,
    pub clickable: Option<bool>,
    pub hover_template: Option<String>,
    pub properties: Option<Vec<(String, JVal)>>,
    pub name: Option<String>,
    pub max_resolution: Option<f64>,
    pub min_resolution: Option<f64>,
    pub opacity: Option<f64>,
    pub visible: Option<bool>,
}

impl Default for LayerAppearance {
    fn default() -> Self {
        // Java field initializer: `properties = new HashMap<>()`
        LayerAppearance {
            id: None,
            attribution: None,
            hoverable: None,
            clickable: None,
            hover_template: None,
            properties: Some(Vec::new()),
            name: None,
            max_resolution: None,
            min_resolution: None,
            opacity: None,
            visible: None,
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct Layer {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub description: Option<String>,
    pub source: Option<Box<LayerDataSource>>,
    pub appearance: Option<Box<LayerAppearance>>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DsKind {
    ImageWms,
    TileWms,
    Wfs,
    Wmts,
    Xyz,
}

#[derive(Debug, Clone, Default)]
pub struct DsBase {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub typ: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
}

#[derive(Debug, Clone)]
pub struct ImageWmsFields {
    pub width: i32,
    pub height: i32,
    pub version: Option<String>,
    pub layer_names: Option<String>,
    pub layer_styles: Option<String>,
    pub requestable_by_path: Option<bool>,
    pub custom_request_path: Option<String>,
}

impl Default for ImageWmsFields {
    fn default() -> Self {
        ImageWmsFields { width: 0, height: 0, version: None, layer_names: None, layer_styles: None, requestable_by_path: None, custom_request_path: None }
    }
}

#[derive(Debug, Clone)]
pub struct TileWmsFields {
    pub tile_grid: Option<Box<TileGrid>>,
    /// Java field initializer: `Boolean.TRUE`.
    pub request_with_tiled: Option<bool>,
}

impl Default for TileWmsFields {
    fn default() -> Self {
        TileWmsFields { tile_grid: None, request_with_tiled: Some(true) }
    }
}

#[derive(Debug, Clone, Default)]
pub struct WfsFields {
    pub version: Option<String>,
    pub type_name: Option<String>,
    pub type_names: Option<String>,
}

#[derive(Debug, Clone)]
pub struct WmtsFields {
    pub tile_grid: Option<Box<TileGrid>>,
    pub urls: Option<Vec<String>>,
    pub wmts_layer: Option<String>,
    pub wmts_style: Option<String>,
    pub projection: Option<String>,
    pub matrix_set: Option<String>,
    pub request_encoding: Option<String>,
    pub capabilities_url: Option<String>,
}

impl Default for WmtsFields {
    fn default() -> Self {
        WmtsFields { tile_grid: None, urls: None, wmts_layer: None, wmts_style: None, projection: None, matrix_set: None, request_encoding: None, capabilities_url: None }
    }
}

#[derive(Debug, Clone)]
pub struct XyzFields {
    pub center: Option<(f64, f64)>,
    pub extent: Option<Box<Extent>>,
    /// Java field initializer: `new ArrayList<Double>()`.
    pub resolutions: Option<Vec<Option<f64>>>,
    pub tile_size: Option<i32>,
}

impl Default for XyzFields {
    fn default() -> Self {
        XyzFields { center: None, extent: None, resolutions: Some(Vec::new()), tile_size: None }
    }
}

#[derive(Debug, Clone, Default)]
pub struct LayerDataSource {
    pub base: DsBase,
    pub kind: Option<DsKind>,
    pub image_wms: Option<ImageWmsFields>,
    pub tile_wms: Option<TileWmsFields>,
    pub wfs: Option<WfsFields>,
    pub wmts: Option<WmtsFields>,
    pub xyz: Option<XyzFields>,
}

impl LayerDataSource {
    pub fn new_of_kind(kind: DsKind) -> LayerDataSource {
        let mut ds = LayerDataSource::default();
        ds.kind = Some(kind);
        match kind {
            DsKind::ImageWms => ds.image_wms = Some(ImageWmsFields::default()),
            DsKind::TileWms => {
                ds.image_wms = Some(ImageWmsFields::default());
                ds.tile_wms = Some(TileWmsFields::default());
            }
            DsKind::Wfs => ds.wfs = Some(WfsFields::default()),
            DsKind::Wmts => ds.wmts = Some(WmtsFields::default()),
            DsKind::Xyz => ds.xyz = Some(XyzFields::default()),
        }
        ds
    }

    pub fn kind(&self) -> DsKind {
        self.kind.unwrap_or(DsKind::ImageWms)
    }
}

// ---------------------------------------------------------------- writing

fn wi(out: &mut String, name: &str, v: &Option<i32>, first: bool) {
    key(out, name, first);
    match v {
        Some(i) => out.push_str(&i.to_string()),
        None => out.push_str("null"),
    }
}

fn wb(out: &mut String, name: &str, v: bool, first: bool) {
    key(out, name, first);
    out.push_str(if v { "true" } else { "false" });
}

fn wbo(out: &mut String, name: &str, v: &Option<bool>, first: bool) {
    key(out, name, first);
    match v {
        Some(b) => out.push_str(if *b { "true" } else { "false" }),
        None => out.push_str("null"),
    }
}

fn ws(out: &mut String, name: &str, v: &Option<String>, first: bool) {
    key(out, name, first);
    match v {
        Some(s) => write_str(out, s),
        None => out.push_str("null"),
    }
}

fn wd(out: &mut String, name: &str, v: &Option<f64>, first: bool) {
    key(out, name, first);
    match v {
        Some(d) => {
            if d.is_nan() || d.is_infinite() {
                // Jackson quotes non-finite doubles
                out.push('"');
                out.push_str(&java_double(*d));
                out.push('"');
            } else {
                out.push_str(&java_double(*d));
            }
        }
        None => out.push_str("null"),
    }
}

fn key(out: &mut String, name: &str, first: bool) {
    if !first {
        out.push(',');
    }
    write_str(out, name);
    out.push(':');
}

fn wpoint(out: &mut String, name: &str, v: &Option<(f64, f64)>, first: bool) {
    key(out, name, first);
    match v {
        Some((x, y)) => {
            out.push_str("{\"x\":");
            wd(out, "x", &Some(*x), true);
            out.push(',');
            wd(out, "y", &Some(*y), false);
            out.push('}');
        }
        None => out.push_str("null"),
    }
}

pub fn write_role(out: &mut String, r: &Role) {
    out.push('{');
    wi(out, "id", &r.id, true);
    ws(out, "name", &r.name, false);
    ws(out, "description", &r.description, false);
    out.push('}');
}

fn write_roles(out: &mut String, roles: &Option<Vec<Role>>) {
    match roles {
        None => out.push_str("null"),
        Some(v) => {
            out.push('[');
            for (i, r) in v.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_role(out, r);
            }
            out.push(']');
        }
    }
}

pub fn write_user(out: &mut String, u: &User) {
    out.push('{');
    wi(out, "id", &u.id, true);
    ws(out, "firstName", &u.first_name, false);
    ws(out, "lastName", &u.last_name, false);
    ws(out, "email", &u.email, false);
    ws(out, "birthday", &u.birthday, false);
    ws(out, "language", &u.language, false);
    ws(out, "accountName", &u.account_name, false);
    wb(out, "active", u.active, false);
    key(out, "roles", false);
    write_roles(out, &u.roles);
    key(out, "userGroups", false);
    match &u.user_groups {
        None => out.push_str("null"),
        Some(v) => {
            out.push('[');
            for (i, g) in v.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(&g.to_string());
            }
            out.push(']');
        }
    }
    out.push('}');
}

pub fn write_user_group(out: &mut String, g: &UserGroup) {
    out.push('{');
    wi(out, "id", &g.id, true);
    ws(out, "name", &g.name, false);
    key(out, "owner", false);
    match &g.owner {
        None => out.push_str("null"),
        Some(u) => write_user(out, u),
    }
    key(out, "members", false);
    match &g.members {
        None => out.push_str("null"),
        Some(v) => {
            out.push('[');
            for (i, u) in v.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_user(out, u);
            }
            out.push(']');
        }
    }
    key(out, "roles", false);
    write_roles(out, &g.roles);
    out.push('}');
}

pub fn write_extent(out: &mut String, e: &Extent) {
    out.push('{');
    wi(out, "id", &e.id, true);
    wpoint(out, "lowerLeft", &e.lower_left, false);
    wpoint(out, "upperRight", &e.upper_right, false);
    out.push('}');
}

fn write_doubles(out: &mut String, v: &[f64]) {
    out.push('[');
    for (i, d) in v.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        if d.is_nan() || d.is_infinite() {
            out.push('"');
            out.push_str(&java_double(*d));
            out.push('"');
        } else {
            out.push_str(&java_double(*d));
        }
    }
    out.push(']');
}

pub fn write_tile_grid(out: &mut String, t: &TileGrid) {
    out.push('{');
    wi(out, "id", &t.id, true);
    ws(out, "type", &t.typ, false);
    wpoint(out, "tileGridOrigin", &t.origin, false);
    key(out, "tileGridExtent", false);
    match &t.extent {
        None => out.push_str("null"),
        Some(e) => write_extent(out, e),
    }
    wi(out, "tileSize", &t.tile_size, false);
    key(out, "tileGridResolutions", false);
    match &t.resolutions {
        None => out.push_str("null"),
        Some(v) => write_doubles(out, v),
    }
    if t.is_wmts {
        key(out, "matrixIds", false);
        match &t.matrix_ids {
            None => out.push_str("null"),
            Some(v) => {
                out.push('[');
                for (i, s) in v.iter().enumerate() {
                    if i > 0 {
                        out.push(',');
                    }
                    write_str(out, s);
                }
                out.push(']');
            }
        }
    }
    out.push('}');
}

pub fn write_layer_appearance(out: &mut String, a: &LayerAppearance) {
    out.push('{');
    wi(out, "id", &a.id, true);
    ws(out, "attribution", &a.attribution, false);
    wbo(out, "hoverable", &a.hoverable, false);
    wbo(out, "clickable", &a.clickable, false);
    ws(out, "hoverTemplate", &a.hover_template, false);
    key(out, "properties", false);
    match &a.properties {
        None => out.push_str("null"),
        Some(v) => {
            out.push('{');
            for (i, (k, val)) in v.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_str(out, k);
                out.push(':');
                out.push_str(&jval_to_json(val));
            }
            out.push('}');
        }
    }
    ws(out, "name", &a.name, false);
    wd(out, "maxResolution", &a.max_resolution, false);
    wd(out, "minResolution", &a.min_resolution, false);
    wd(out, "opacity", &a.opacity, false);
    wbo(out, "visible", &a.visible, false);
    out.push('}');
}

pub fn jval_to_json(v: &JVal) -> String {
    let mut out = String::new();
    write_jval(&mut out, v);
    out
}

pub fn write_jval(out: &mut String, v: &JVal) {
    match v {
        JVal::Null => out.push_str("null"),
        JVal::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        JVal::Int(i) => out.push_str(&i.to_string()),
        JVal::Float(f) => {
            if f.is_nan() || f.is_infinite() {
                out.push('"');
                out.push_str(&java_double(*f));
                out.push('"');
            } else {
                out.push_str(&java_double(*f));
            }
        }
        JVal::Str(s) => write_str(out, s),
        JVal::Arr(a) => {
            out.push('[');
            for (i, v) in a.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_jval(out, v);
            }
            out.push(']');
        }
        JVal::Obj(o) => {
            out.push('{');
            for (i, (k, v)) in o.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_str(out, k);
                out.push(':');
                write_jval(out, v);
            }
            out.push('}');
        }
    }
}

pub fn write_layer(out: &mut String, l: &Layer) {
    out.push('{');
    wi(out, "id", &l.id, true);
    ws(out, "name", &l.name, false);
    ws(out, "description", &l.description, false);
    key(out, "source", false);
    match &l.source {
        None => out.push_str("null"),
        Some(d) => write_layer_data_source(out, d),
    }
    key(out, "appearance", false);
    match &l.appearance {
        None => out.push_str("null"),
        Some(a) => write_layer_appearance(out, a),
    }
    out.push('}');
}

pub fn write_layer_data_source(out: &mut String, d: &LayerDataSource) {
    out.push('{');
    let b = &d.base;
    wi(out, "id", &b.id, true);
    ws(out, "name", &b.name, false);
    ws(out, "type", &b.typ, false);
    ws(out, "url", &b.url, false);
    ws(out, "format", &b.format, false);
    match d.kind() {
        DsKind::ImageWms | DsKind::TileWms => {
            if let Some(im) = &d.image_wms {
                out.push_str(",\"width\":");
                out.push_str(&im.width.to_string());
                out.push_str(",\"height\":");
                out.push_str(&im.height.to_string());
                ws(out, "version", &im.version, false);
                ws(out, "layerNames", &im.layer_names, false);
                ws(out, "layerStyles", &im.layer_styles, false);
                wbo(out, "requestableByPath", &im.requestable_by_path, false);
                ws(out, "customRequestPath", &im.custom_request_path, false);
            }
            if d.kind() == DsKind::TileWms {
                if let Some(t) = &d.tile_wms {
                    key(out, "tileGrid", false);
                    match &t.tile_grid {
                        None => out.push_str("null"),
                        Some(tg) => write_tile_grid(out, tg),
                    }
                    wbo(out, "requestWithTiled", &t.request_with_tiled, false);
                }
            }
        }
        DsKind::Wfs => {
            if let Some(w) = &d.wfs {
                ws(out, "version", &w.version, false);
                ws(out, "typeName", &w.type_name, false);
                ws(out, "typeNames", &w.type_names, false);
            }
        }
        DsKind::Wmts => {
            if let Some(m) = &d.wmts {
                key(out, "tileGrid", false);
                match &m.tile_grid {
                    None => out.push_str("null"),
                    Some(tg) => write_tile_grid(out, tg),
                }
                key(out, "urls", false);
                match &m.urls {
                    None => out.push_str("null"),
                    Some(v) => {
                        out.push('[');
                        for (i, s) in v.iter().enumerate() {
                            if i > 0 {
                                out.push(',');
                            }
                            write_str(out, s);
                        }
                        out.push(']');
                    }
                }
                ws(out, "wmtsLayer", &m.wmts_layer, false);
                ws(out, "wmtsStyle", &m.wmts_style, false);
                ws(out, "projection", &m.projection, false);
                ws(out, "matrixSet", &m.matrix_set, false);
                ws(out, "requestEncoding", &m.request_encoding, false);
                ws(out, "capabilitiesUrl", &m.capabilities_url, false);
            }
        }
        DsKind::Xyz => {
            if let Some(x) = &d.xyz {
                wpoint(out, "center", &x.center, false);
                key(out, "extent", false);
                match &x.extent {
                    None => out.push_str("null"),
                    Some(e) => write_extent(out, e),
                }
                key(out, "resolutions", false);
                match &x.resolutions {
                    None => out.push_str("null"),
                    Some(v) => {
                        out.push('[');
                        for (i, r) in v.iter().enumerate() {
                            if i > 0 {
                                out.push(',');
                            }
                            match r {
                                Some(f) => {
                                    if f.is_nan() || f.is_infinite() {
                                        out.push('"');
                                        out.push_str(&java_double(*f));
                                        out.push('"');
                                    } else {
                                        out.push_str(&java_double(*f));
                                    }
                                }
                                None => out.push_str("null"),
                            }
                        }
                        out.push(']');
                    }
                }
                wi(out, "tileSize", &x.tile_size, false);
            }
        }
    }
    out.push('}');
}

// ---------------------------------------------------------------- restrict

/// The filterable/restrictable (non-static private primitive/wrapper/String)
/// field names, in `EntityUtil.getFilterableOrRestrictableFieldNames` order.
pub fn restrictable_fields(resource: &str) -> &'static [&'static str] {
    match resource {
        "users" => &["id", "firstName", "lastName", "email", "accountName", "password", "active"],
        "groups" => &["id", "name"],
        "roles" => &["id", "name", "description"],
        "layers" => &["id", "name", "description"],
        "layerdatasources" => &["id", "name", "type", "url", "format"],
        "layerappearances" => &[
            "id",
            "attribution",
            "hoverable",
            "clickable",
            "hoverTemplate",
            "name",
            "maxResolution",
            "minResolution",
            "opacity",
            "visible",
        ],
        _ => &[],
    }
}

/// Case-insensitive intersection of requested and restrictable field names,
/// keeping the canonical (Java) casing. `None` when nothing matches, meaning
/// "no restriction".
pub fn determine_restrict_fields(requested: &[&str], resource: &str) -> Option<Vec<String>> {
    let restrictable = restrictable_fields(resource);
    let mut out = Vec::new();
    for f in restrictable {
        if requested.iter().any(|r| f.eq_ignore_ascii_case(r)) {
            out.push(f.to_string());
        }
    }
    if out.is_empty() {
        None
    } else {
        Some(out)
    }
}

/// Apply the `output:only` restriction: every field not in the list is reset
/// to the Java constructor default.
pub fn apply_restriction(resource: &str, fields: &[String], id: i32) -> String {
    let _ = (resource, fields, id);
    String::new()
}

// ---------------------------------------------------------------- filter

#[derive(Debug, Clone, PartialEq)]
pub enum FilterVal {
    Int(i32),
    Str(String),
    Bool(bool),
    Double(f64),
    /// Value could not be cast: matches nothing (`eq(field, null)`).
    None,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum FieldType {
    Int,
    Str,
    BoolPrim,
    BoolWrap,
    Double,
}

pub fn filter_field_type(resource: &str, field: &str) -> Option<FieldType> {
    let fields = restrictable_fields(resource);
    let f = fields.iter().find(|f| f.eq_ignore_ascii_case(field))?;
    let resource = resource;
    Some(match (resource, f.as_ref()) {
        (_, "id") => FieldType::Int,
        (_, "active") => FieldType::BoolPrim,
        (_, "hoverable") | (_, "clickable") | (_, "visible") => FieldType::BoolWrap,
        (_, "maxResolution") | (_, "minResolution") | (_, "opacity") => FieldType::Double,
        _ => FieldType::Str,
    })
}

/// commons-beanutils `ConvertUtils.convert(value, targetType)` semantics.
pub fn cast_filter_value(ft: FieldType, raw: &str) -> FilterVal {
    match ft {
        FieldType::Str => FilterVal::Str(raw.to_string()),
        FieldType::Int => match raw.parse::<i64>() {
            Ok(v) if v >= i32::MIN as i64 && v <= i32::MAX as i64 => FilterVal::Int(v as i32),
            _ => FilterVal::None,
        },
        FieldType::Double => match raw.parse::<f64>() {
            Ok(v) => FilterVal::Double(v),
            Err(_) => FilterVal::None,
        },
        FieldType::BoolPrim | FieldType::BoolWrap => {
            let l = raw.to_ascii_lowercase();
            if ["true", "yes", "y", "on", "1"].contains(&l.as_str()) {
                FilterVal::Bool(true)
            } else if ["false", "no", "n", "off", "0"].contains(&l.as_str()) {
                FilterVal::Bool(false)
            } else if ft == FieldType::BoolPrim {
                // BooleanConverter default for the primitive type: false
                FilterVal::Bool(false)
            } else {
                FilterVal::None
            }
        }
    }
}

// ---------------------------------------------------- Java-serialized values

pub fn resolutions_to_bytes(vals: &[Option<f64>]) -> Vec<Vec<u8>> {
    vals.iter()
        .map(|v| match v {
            Some(f) => javaser::encode_double(*f),
            None => javaser::encode_null(),
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn user_json_shape() {
        let u = User {
            id: Some(3),
            first_name: Some("A".into()),
            last_name: Some("B".into()),
            email: None,
            birthday: None,
            language: None,
            account_name: Some("admin".into()),
            password: Some("secret".into()),
            active: true,
            roles: Some(vec![Role { id: Some(1), name: Some("ROLE_ADMIN".into()), description: Some("d".into()) }]),
            user_groups: Some(vec![5, 6]),
        };
        let mut s = String::new();
        write_user(&mut s, &u);
        assert_eq!(
            s,
            "{\"id\":3,\"firstName\":\"A\",\"lastName\":\"B\",\"email\":null,\"birthday\":null,\"language\":null,\"accountName\":\"admin\",\"active\":true,\"roles\":[{\"id\":1,\"name\":\"ROLE_ADMIN\",\"description\":\"d\"}],\"userGroups\":[5,6]}"
        );
    }

    #[test]
    fn restrict_fields_case_insensitive() {
        let r = determine_restrict_fields(&["ID", "AccountNAME"], "users").unwrap();
        assert_eq!(r, vec!["id".to_string(), "accountName".to_string()]);
        assert!(determine_restrict_fields(&["nope"], "users").is_none());
        assert!(determine_restrict_fields(&[], "users").is_none());
    }

    #[test]
    fn casting_semantics() {
        assert_eq!(cast_filter_value(FieldType::BoolPrim, "maybe"), FilterVal::Bool(false));
        assert_eq!(cast_filter_value(FieldType::BoolPrim, "1"), FilterVal::Bool(true));
        assert_eq!(cast_filter_value(FieldType::BoolWrap, "maybe"), FilterVal::None);
        assert_eq!(cast_filter_value(FieldType::Int, "abc"), FilterVal::None);
        assert_eq!(cast_filter_value(FieldType::Int, "5"), FilterVal::Int(5));
        assert_eq!(cast_filter_value(FieldType::Double, "2.5"), FilterVal::Double(2.5));
    }
}

metadata.rawInput:
{"content":"//! Entity model of the ported REST slice: User, UserGroup, Role, Layer,
//! LayerDataSource (+ subtypes), LayerAppearance, Extent, TileGrid.
//!
//! Every struct mirrors the Java entity field-for-field, including the
//! field defaults produced by the Java no-argument constructors (relevant
//! for `output:only` restricted projections and for JSON deserialization).

use crate::javaser;
use crate::json::{java_double, write_str, JVal};

#[derive(Debug, Clone, Default)]
pub struct Role {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub description: Option<String>,
}

#[derive(Debug, Clone)]
pub struct User {
    pub id: Option<i32>,
    pub first_name: Option<String>,
    pub last_name: Option<String>,
    pub email: Option<String>,
    /// ISO date string (YYYY-MM-DD), as joda-time prints it.
    pub birthday: Option<String>,
    pub language: Option<String>,
    pub account_name: Option<String>,
    pub password: Option<String>,
    pub active: bool,
    /// `None` represents a JSON `null` collection.
    pub roles: Option<Vec<Role>>,
    pub user_groups: Option<Vec<i32>>,
}

impl Default for User {
    fn default() -> Self {
        // Java field initializers: `roles = new HashSet<>()`, `userGroups = new HashSet<>()`
        User {
            id: None,
            first_name: None,
            last_name: None,
            email: None,
            birthday: None,
            language: None,
            account_name: None,
            password: None,
            active: false,
            roles: Some(Vec::new()),
            user_groups: Some(Vec::new()),
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct UserGroup {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub owner: Option<Box<User>>,
    pub members: Option<Vec<User>>,
    pub roles: Option<Vec<Role>>,
}

#[derive(Debug, Clone, Default)]
pub struct Extent {
    pub id: Option<i32>,
    pub lower_left: Option<(f64, f64)>,
    pub upper_right: Option<(f64, f64)>,
}

#[derive(Debug, Clone)]
pub struct TileGrid {
    pub id: Option<i32>,
    pub typ: Option<String>,
    pub origin: Option<(f64, f64)>,
    pub extent: Option<Box<Extent>>,
    /// Java constructor default is 256.
    pub tile_size: Option<i32>,
    pub resolutions: Option<Vec<f64>>,
    /// Only present for WmtsTileGrid.
    pub matrix_ids: Option<Vec<String>>,
    pub is_wmts: bool,
}

impl Default for TileGrid {
    fn default() -> Self {
        // Java no-arg TileGrid constructor: `tileSize = Integer.valueOf(256)`.
        TileGrid {
            id: None,
            typ: None,
            origin: None,
            extent: None,
            tile_size: Some(256),
            resolutions: None,
            matrix_ids: None,
            is_wmts: false,
        }
    }
}

impl TileGrid {
    pub fn new_wmts_default() -> TileGrid {
        let mut tg = TileGrid::default();
        tg.is_wmts = true;
        tg
    }
}

#[derive(Debug, Clone, Default)]
pub struct LayerAppearance {
    pub id: Option<i32>,
    pub attribution: Option<String>,
    pub hoverable: Option<bool>,
    pub clickable: Option<bool>,
    pub hover_template: Option<String>,
    pub properties: Option<Vec<(String, JVal)>>,
    pub name: Option<String>,
    pub max_resolution: Option<f64>,
    pub min_resolution: Option<f64>,
    pub opacity: Option<f64>,
    pub visible: Option<bool>,
}

impl Default for LayerAppearance {
    fn default() -> Self {
        // Java field initializer: `properties = new HashMap<>()`
        LayerAppearance {
            id: None,
            attribution: None,
            hoverable: None,
            clickable: None,
            hover_template: None,
            properties: Some(Vec::new()),
            name: None,
            max_resolution: None,
            min_resolution: None,
            opacity: None,
            visible: None,
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct Layer {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub description: Option<String>,
    pub source: Option<Box<LayerDataSource>>,
    pub appearance: Option<Box<LayerAppearance>>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DsKind {
    ImageWms,
    TileWms,
    Wfs,
    Wmts,
    Xyz,
}

#[derive(Debug, Clone, Default)]
pub struct DsBase {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub typ: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
}

#[derive(Debug, Clone)]
pub struct ImageWmsFields {
    pub width: i32,
    pub height: i32,
    pub version: Option<String>,
    pub layer_names: Option<String>,
    pub layer_styles: Option<String>,
    pub requestable_by_path: Option<bool>,
    pub custom_request_path: Option<String>,
}

impl Default for ImageWmsFields {
    fn default() -> Self {
        ImageWmsFields { width: 0, height: 0, version: None, layer_names: None, layer_styles: None, requestable_by_path: None, custom_request_path: None }
    }
}

#[derive(Debug, Clone)]
pub struct TileWmsFields {
    pub tile_grid: Option<Box<TileGrid>>,
    /// Java field initializer: `Boolean.TRUE`.
    pub request_with_tiled: Option<bool>,
}

impl Default for TileWmsFields {
    fn default() -> Self {
        TileWmsFields { tile_grid: None, request_with_tiled: Some(true) }
    }
}

#[derive(Debug, Clone, Default)]
pub struct WfsFields {
    pub version: Option<String>,
    pub type_name: Option<String>,
    pub type_names: Option<String>,
}

#[derive(Debug, Clone)]
pub struct WmtsFields {
    pub tile_grid: Option<Box<TileGrid>>,
    pub urls: Option<Vec<String>>,
    pub wmts_layer: Option<String>,
    pub wmts_style: Option<String>,
    pub projection: Option<String>,
    pub matrix_set: Option<String>,
    pub request_encoding: Option<String>,
    pub capabilities_url: Option<String>,
}

impl Default for WmtsFields {
    fn default() -> Self {
        WmtsFields { tile_grid: None, urls: None, wmts_layer: None, wmts_style: None, projection: None, matrix_set: None, request_encoding: None, capabilities_url: None }
    }
}

#[derive(Debug, Clone)]
pub struct XyzFields {
    pub center: Option<(f64, f64)>,
    pub extent: Option<Box<Extent>>,
    /// Java field initializer: `new ArrayList<Double>()`.
    pub resolutions: Option<Vec<Option<f64>>>,
    pub tile_size: Option<i32>,
}

impl Default for XyzFields {
    fn default() -> Self {
        XyzFields { center: None, extent: None, resolutions: Some(Vec::new()), tile_size: None }
    }
}

#[derive(Debug, Clone, Default)]
pub struct LayerDataSource {
    pub base: DsBase,
    pub kind: Option<DsKind>,
    pub image_wms: Option<ImageWmsFields>,
    pub tile_wms: Option<TileWmsFields>,
    pub wfs: Option<WfsFields>,
    pub wmts: Option<WmtsFields>,
    pub xyz: Option<XyzFields>,
}

impl LayerDataSource {
    pub fn new_of_kind(kind: DsKind) -> LayerDataSource {
        let mut ds = LayerDataSource::default();
        ds.kind = Some(kind);
        match kind {
            DsKind::ImageWms => ds.image_wms = Some(ImageWmsFields::default()),
            DsKind::TileWms => {
                ds.image_wms = Some(ImageWmsFields::default());
                ds.tile_wms = Some(TileWmsFields::default());
            }
            DsKind::Wfs => ds.wfs = Some(WfsFields::default()),
            DsKind::Wmts => ds.wmts = Some(WmtsFields::default()),
            DsKind::Xyz => ds.xyz = Some(XyzFields::default()),
        }
        ds
    }

    pub fn kind(&self) -> DsKind {
        self.kind.unwrap_or(DsKind::ImageWms)
    }
}

// ---------------------------------------------------------------- writing

fn wi(out: &mut String, name: &str, v: &Option<i32>, first: bool) {
    key(out, name, first);
    match v {
        Some(i) => out.push_str(&i.to_string()),
        None => out.push_str("null"),
    }
}

fn wb(out: &mut String, name: &str, v: bool, first: bool) {
    key(out, name, first);
    out.push_str(if v { "true" } else { "false" });
}

fn wbo(out: &mut String, name: &str, v: &Option<bool>, first: bool) {
    key(out, name, first);
    match v {
        Some(b) => out.push_str(if *b { "true" } else { "false" }),
        None => out.push_str("null"),
    }
}

fn ws(out: &mut String, name: &str, v: &Option<String>, first: bool) {
    key(out, name, first);
    match v {
        Some(s) => write_str(out, s),
        None => out.push_str("null"),
    }
}

fn wd(out: &mut String, name: &str, v: &Option<f64>, first: bool) {
    key(out, name, first);
    match v {
        Some(d) => {
            if d.is_nan() || d.is_infinite() {
                // Jackson quotes non-finite doubles
                out.push('"');
                out.push_str(&java_double(*d));
                out.push('"');
            } else {
                out.push_str(&java_double(*d));
            }
        }
        None => out.push_str("null"),
    }
}

fn key(out: &mut String, name: &str, first: bool) {
    if !first {
        out.push(',');
    }
    write_str(out, name);
    out.push(':');
}

fn wpoint(out: &mut String, name: &str, v: &Option<(f64, f64)>, first: bool) {
    key(out, name, first);
    match v {
        Some((x, y)) => {
            out.push_str("{\"x\":");
            wd(out, "x", &Some(*x), true);
            out.push(',');
            wd(out, "y", &Some(*y), false);
            out.push('}');
        }
        None => out.push_str("null"),
    }
}

pub fn write_role(out: &mut String, r: &Role) {
    out.push('{');
    wi(out, "id", &r.id, true);
    ws(out, "name", &r.name, false);
    ws(out, "description", &r.description, false);
    out.push('}');
}

fn write_roles(out: &mut String, roles: &Option<Vec<Role>>) {
    match roles {
        None => out.push_str("null"),
        Some(v) => {
            out.push('[');
            for (i, r) in v.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_role(out, r);
            }
            out.push(']');
        }
    }
}

pub fn write_user(out: &mut String, u: &User) {
    out.push('{');
    wi(out, "id", &u.id, true);
    ws(out, "firstName", &u.first_name, false);
    ws(out, "lastName", &u.last_name, false);
    ws(out, "email", &u.email, false);
    ws(out, "birthday", &u.birthday, false);
    ws(out, "language", &u.language, false);
    ws(out, "accountName", &u.account_name, false);
    wb(out, "active", u.active, false);
    key(out, "roles", false);
    write_roles(out, &u.roles);
    key(out, "userGroups", false);
    match &u.user_groups {
        None => out.push_str("null"),
        Some(v) => {
            out.push('[');
            for (i, g) in v.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(&g.to_string());
            }
            out.push(']');
        }
    }
    out.push('}');
}

pub fn write_user_group(out: &mut String, g: &UserGroup) {
    out.push('{');
    wi(out, "id", &g.id, true);
    ws(out, "name", &g.name, false);
    key(out, "owner", false);
    match &g.owner {
        None => out.push_str("null"),
        Some(u) => write_user(out, u),
    }
    key(out, "members", false);
    match &g.members {
        None => out.push_str("null"),
        Some(v) => {
            out.push('[');
            for (i, u) in v.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_user(out, u);
            }
            out.push(']');
        }
    }
    key(out, "roles", false);
    write_roles(out, &g.roles);
    out.push('}');
}

pub fn write_extent(out: &mut String, e: &Extent) {
    out.push('{');
    wi(out, "id", &e.id, true);
    wpoint(out, "lowerLeft", &e.lower_left, false);
    wpoint(out, "upperRight", &e.upper_right, false);
    out.push('}');
}

fn write_doubles(out: &mut String, v: &[f64]) {
    out.push('[');
    for (i, d) in v.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        if d.is_nan() || d.is_infinite() {
            out.push('"');
            out.push_str(&java_double(*d));
            out.push('"');
        } else {
            out.push_str(&java_double(*d));
        }
    }
    out.push(']');
}

pub fn write_tile_grid(out: &mut String, t: &TileGrid) {
    out.push('{');
    wi(out, "id", &t.id, true);
    ws(out, "type", &t.typ, false);
    wpoint(out, "tileGridOrigin", &t.origin, false);
    key(out, "tileGridExtent", false);
    match &t.extent {
        None => out.push_str("null"),
        Some(e) => write_extent(out, e),
    }
    wi(out, "tileSize", &t.tile_size, false);
    key(out, "tileGridResolutions", false);
    match &t.resolutions {
        None => out.push_str("null"),
        Some(v) => write_doubles(out, v),
    }
    if t.is_wmts {
        key(out, "matrixIds", false);
        match &t.matrix_ids {
            None => out.push_str("null"),
            Some(v) => {
                out.push('[');
                for (i, s) in v.iter().enumerate() {
                    if i > 0 {
                        out.push(',');
                    }
                    write_str(out, s);
                }
                out.push(']');
            }
        }
    }
    out.push('}');
}

pub fn write_layer_appearance(out: &mut String, a: &LayerAppearance) {
    out.push('{');
    wi(out, "id", &a.id, true);
    ws(out, "attribution", &a.attribution, false);
    wbo(out, "hoverable", &a.hoverable, false);
    wbo(out, "clickable", &a.clickable, false);
    ws(out, "hoverTemplate", &a.hover_template, false);
    key(out, "properties", false);
    match &a.properties {
        None => out.push_str("null"),
        Some(v) => {
            out.push('{');
            for (i, (k, val)) in v.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_str(out, k);
                out.push(':');
                out.push_str(&jval_to_json(val));
            }
            out.push('}');
        }
    }
    ws(out, "name", &a.name, false);
    wd(out, "maxResolution", &a.max_resolution, false);
    wd(out, "minResolution", &a.min_resolution, false);
    wd(out, "opacity", &a.opacity, false);
    wbo(out, "visible", &a.visible, false);
    out.push('}');
}

pub fn jval_to_json(v: &JVal) -> String {
    let mut out = String::new();
    write_jval(&mut out, v);
    out
}

pub fn write_jval(out: &mut String, v: &JVal) {
    match v {
        JVal::Null => out.push_str("null"),
        JVal::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        JVal::Int(i) => out.push_str(&i.to_string()),
        JVal::Float(f) => {
            if f.is_nan() || f.is_infinite() {
                out.push('"');
                out.push_str(&java_double(*f));
                out.push('"');
            } else {
                out.push_str(&java_double(*f));
            }
        }
        JVal::Str(s) => write_str(out, s),
        JVal::Arr(a) => {
            out.push('[');
            for (i, v) in a.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_jval(out, v);
            }
            out.push(']');
        }
        JVal::Obj(o) => {
            out.push('{');
            for (i, (k, v)) in o.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_str(out, k);
                out.push(':');
                write_jval(out, v);
            }
            out.push('}');
        }
    }
}

pub fn write_layer(out: &mut String, l: &Layer) {
    out.push('{');
    wi(out, "id", &l.id, true);
    ws(out, "name", &l.name, false);
    ws(out, "description", &l.description, false);
    key(out, "source", false);
    match &l.source {
        None => out.push_str("null"),
        Some(d) => write_layer_data_source(out, d),
    }
    key(out, "appearance", false);
    match &l.appearance {
        None => out.push_str("null"),
        Some(a) => write_layer_appearance(out, a),
    }
    out.push('}');
}

pub fn write_layer_data_source(out: &mut String, d: &LayerDataSource) {
    out.push('{');
    let b = &d.base;
    wi(out, "id", &b.id, true);
    ws(out, "name", &b.name, false);
    ws(out, "type", &b.typ, false);
    ws(out, "url", &b.url, false);
    ws(out, "format", &b.format, false);
    match d.kind() {
        DsKind::ImageWms | DsKind::TileWms => {
            if let Some(im) = &d.image_wms {
                out.push_str(",\"width\":");
                out.push_str(&im.width.to_string());
                out.push_str(",\"height\":");
                out.push_str(&im.height.to_string());
                ws(out, "version", &im.version, false);
                ws(out, "layerNames", &im.layer_names, false);
                ws(out, "layerStyles", &im.layer_styles, false);
                wbo(out, "requestableByPath", &im.requestable_by_path, false);
                ws(out, "customRequestPath", &im.custom_request_path, false);
            }
            if d.kind() == DsKind::TileWms {
                if let Some(t) = &d.tile_wms {
                    key(out, "tileGrid", false);
                    match &t.tile_grid {
                        None => out.push_str("null"),
                        Some(tg) => write_tile_grid(out, tg),
                    }
                    wbo(out, "requestWithTiled", &t.request_with_tiled, false);
                }
            }
        }
        DsKind::Wfs => {
            if let Some(w) = &d.wfs {
                ws(out, "version", &w.version, false);
                ws(out, "typeName", &w.type_name, false);
                ws(out, "typeNames", &w.type_names, false);
            }
        }
        DsKind::Wmts => {
            if let Some(m) = &d.wmts {
                key(out, "tileGrid", false);
                match &m.tile_grid {
                    None => out.push_str("null"),
                    Some(tg) => write_tile_grid(out, tg),
                }
                key(out, "urls", false);
                match &m.urls {
                    None => out.push_str("null"),
                    Some(v) => {
                        out.push('[');
                        for (i, s) in v.iter().enumerate() {
                            if i > 0 {
                                out.push(',');
                            }
                            write_str(out, s);
                        }
                        out.push(']');
                    }
                }
                ws(out, "wmtsLayer", &m.wmts_layer, false);
                ws(out, "wmtsStyle", &m.wmts_style, false);
                ws(out, "projection", &m.projection, false);
                ws(out, "matrixSet", &m.matrix_set, false);
                ws(out, "requestEncoding", &m.request_encoding, false);
                ws(out, "capabilitiesUrl", &m.capabilities_url, false);
            }
        }
        DsKind::Xyz => {
            if let Some(x) = &d.xyz {
                wpoint(out, "center", &x.center, false);
                key(out, "extent", false);
                match &x.extent {
                    None => out.push_str("null"),
                    Some(e) => write_extent(out, e),
                }
                key(out, "resolutions", false);
                match &x.resolutions {
                    None => out.push_str("null"),
                    Some(v) => {
                        out.push('[');
                        for (i, r) in v.iter().enumerate() {
                            if i > 0 {
                                out.push(',');
                            }
                            match r {
                                Some(f) => {
                                    if f.is_nan() || f.is_infinite() {
                                        out.push('"');
                                        out.push_str(&java_double(*f));
                                        out.push('"');
                                    } else {
                                        out.push_str(&java_double(*f));
                                    }
                                }
                                None => out.push_str("null"),
                            }
                        }
                        out.push(']');
                    }
                }
                wi(out, "tileSize", &x.tile_size, false);
            }
        }
    }
    out.push('}');
}

