//! Jackson-compatible JSON deserialization of the entity model.
//!
//! Mirrors `ObjectMapper.readValue` for POST bodies and
//! `objectMapper.readerForUpdating(entity).readValue(json)` for PUT bodies:
//! the passed entity is pre-populated (with loaded values or with the Java
//! constructor defaults) and only keys present in the JSON object are
//! applied. Unknown keys are rejected exactly like Jackson's default
//! `FAIL_ON_UNKNOWN_PROPERTIES`; `@JsonIgnore` properties are silently
//! skipped; the abstract `LayerDataSource` cannot be built from JSON at all.

use crate::json::JVal;
use crate::model::*;

#[derive(Debug)]
pub struct DeErr;

const IGNORED: [&str; 4] = ["created", "modified", "userPermissions", "groupPermissions"];

fn obj<'a>(v: &'a JVal) -> Result<&'a Vec<(String, JVal)>, DeErr> {
    match v {
        JVal::Obj(o) => Ok(o),
        _ => Err(DeErr),
    }
}

/// Jackson `String` deserialization: strings pass through, scalars coerce.
fn jstr(v: &JVal) -> Result<Option<String>, DeErr> {
    match v {
        JVal::Null => Ok(None),
        JVal::Str(s) => Ok(Some(s.clone())),
        JVal::Int(i) => Ok(Some(i.to_string())),
        JVal::Float(f) => Ok(Some(crate::json::java_double(*f))),
        JVal::Bool(b) => Ok(Some(if *b { "true".into() } else { "false".into() })),
        _ => Err(DeErr),
    }
}

fn jdouble(v: &JVal) -> Result<Option<f64>, DeErr> {
    match v {
        JVal::Null => Ok(None),
        JVal::Int(i) => Ok(Some(*i as f64)),
        JVal::Float(f) => Ok(Some(*f)),
        JVal::Str(s) => s.parse::<f64>().map(Some).map_err(|_| DeErr),
        _ => Err(DeErr),
    }
}

/// Jackson `Integer` deserialization (wrapper type; JSON null becomes None).
fn jint(v: &JVal) -> Result<Option<i32>, DeErr> {
    match v {
        JVal::Null => Ok(None),
        JVal::Int(i) => {
            if *i >= i32::MIN as i64 && *i <= i32::MAX as i64 {
                Ok(Some(*i as i32))
            } else {
                Err(DeErr)
            }
        }
        JVal::Float(f) => {
            if f.fract() == 0.0 && *f >= i32::MIN as f64 && *f <= i32::MAX as f64 {
                Ok(Some(*f as i32))
            } else {
                Err(DeErr)
            }
        }
        JVal::Str(s) => s.trim().parse::<i32>().map(Some).map_err(|_| DeErr),
        _ => Err(DeErr),
    }
}

/// Jackson primitive `int` deserialization (JSON null becomes 0).
fn jint_prim(v: &JVal) -> Result<i32, DeErr> {
    Ok(jint(v).unwrap_or(None).unwrap_or(0))
}

fn jbool(v: &JVal) -> Result<Option<bool>, DeErr> {
    match v {
        JVal::Null => Ok(None),
        JVal::Bool(b) => Ok(Some(*b)),
        JVal::Str(s) => match s.as_str() {
            "true" => Ok(Some(true)),
            "false" => Ok(Some(false)),
            _ => Err(DeErr),
        },
        _ => Err(DeErr),
    }
}

/// joda-time `LocalDate` (ISO `YYYY-MM-DD`, calendar-validated).
fn jdate(v: &JVal) -> Result<Option<String>, DeErr> {
    match v {
        JVal::Null => Ok(None),
        JVal::Str(s) => {
            if valid_iso_date(s) {
                Ok(Some(s.clone()))
            } else {
                Err(DeErr)
            }
        }
        _ => Err(DeErr),
    }
}

pub fn valid_iso_date(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() != 10 || b[4] != b'-' || b[7] != b'-' {
        return false;
    }
    let num = |from: usize, to: usize| s.get(from..to).and_then(|x| x.parse::<u32>().ok());
    let (y, m, d) = match (num(0, 4), num(5, 7), num(8, 10)) {
        (Some(y), Some(m), Some(d)) => (y, m, d),
        _ => return false,
    };
    if !(1..=12).contains(&m) || d < 1 {
        return false;
    }
    let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    let max = match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if leap {
                29
            } else {
                28
            }
        }
        _ => 0,
    };
    d <= max
}

/// `java.awt.geom.Point2D$Double` deserialization: public fields x/y,
/// defaults 0.0/0.0, unknown keys rejected.
fn jpoint(v: &JVal) -> Result<Option<(f64, f64)>, DeErr> {
    match v {
        JVal::Null => Ok(None),
        JVal::Obj(_) => {
            let o = obj(v)?;
            let mut x = 0.0f64;
            let mut y = 0.0f64;
            for (k, val) in o.iter() {
                match k.as_str() {
                    "x" => {
                        x = jdouble(val)?.unwrap_or(0.0);
                    }
                    "y" => {
                        y = jdouble(val)?.unwrap_or(0.0);
                    }
                    _ => return Err(DeErr),
                }
            }
            Ok(Some((x, y)))
        }
        _ => Err(DeErr),
    }
}

// ------------------------------------------------------------- apply fns

pub fn apply_role(r: &mut Role, v: &JVal) -> Result<(), DeErr> {
    let o = obj(v)?;
    for (k, val) in o.iter() {
        match k.as_str() {
            "id" => r.id = jint(val)?,
            "name" => r.name = jstr(val)?,
            "description" => r.description = jstr(val)?,
            other if IGNORED.contains(&other) => {}
            _ => return Err(DeErr),
        }
    }
    Ok(())
}

pub fn role_from_json(v: &JVal) -> Result<Role, DeErr> {
    let mut r = Role::default();
    apply_role(&mut r, v)?;
    Ok(r)
}

fn roles_from_json(v: &JVal) -> Result<Option<Vec<Role>>, DeErr> {
    match v {
        JVal::Null => Ok(None),
        JVal::Arr(a) => {
            let mut out = Vec::with_capacity(a.len());
            for e in a {
                out.push(role_from_json(e)?);
            }
            Ok(Some(out))
        }
        _ => Err(DeErr),
    }
}

pub fn apply_user(u: &mut User, v: &JVal) -> Result<(), DeErr> {
    let o = obj(v)?;
    for (k, val) in o.iter() {
        match k.as_str() {
            "id" => u.id = jint(val)?,
            "firstName" => u.first_name = jstr(val)?,
            "lastName" => u.last_name = jstr(val)?,
            "email" => u.email = jstr(val)?,
            "birthday" => u.birthday = jdate(val)?,
            "language" => match val {
                JVal::Null => u.language = None,
                JVal::Str(s) => u.language = Some(s.clone()),
                _ => return Err(DeErr),
            },
            "accountName" => u.account_name = jstr(val)?,
            "password" => u.password = jstr(val)?,
            "active" => u.active = jbool(val)?.unwrap_or(false),
            "roles" => u.roles = roles_from_json(val)?,
            "userGroups" => match val {
                JVal::Null => u.user_groups = None,
                JVal::Arr(a) => {
                    let mut out = Vec::with_capacity(a.len());
                    for e in a {
                        match e {
                            JVal::Int(i) => {
                                if *i >= i32::MIN as i64 && *i <= i32::MAX as i64 {
                                    out.push(Some(*i as i32));
                                } else {
                                    return Err(DeErr);
                                }
                            }
                            JVal::Float(f) if f.fract() == 0.0 => out.push(Some(*f as i32)),
                            JVal::Str(s) => match s.trim().parse::<i32>() {
                                Ok(i) => out.push(Some(i)),
                                Err(_) => return Err(DeErr),
                            },
                            // null / unresolvable id: Jackson resolves to null
                            _ => out.push(None),
                        }
                    }
                    u.user_groups = Some(out.into_iter().filter_map(|x| x).collect());
                    // remember null elements so the join insert fails later
                    if a.iter().any(|e| !matches!(e, JVal::Int(_) | JVal::Float(_) | JVal::Str(_))) {
                        u.has_null_group_refs = true;
                    }
                }
                _ => return Err(DeErr),
            },
            other if IGNORED.contains(&other) => {}
            _ => return Err(DeErr),
        }
    }
    Ok(())
}

pub fn user_from_json(v: &JVal) -> Result<User, DeErr> {
    let mut u = User::default();
    apply_user(&mut u, v)?;
    Ok(u)
}

pub fn apply_user_group(g: &mut UserGroup, v: &JVal) -> Result<(), DeErr> {
    let o = obj(v)?;
    for (k, val) in o.iter() {
        match k.as_str() {
            "id" => g.id = jint(val)?,
            "name" => g.name = jstr(val)?,
            "owner" => match val {
                JVal::Null => g.owner = None,
                _ => {
                    let mut u = User::default();
                    apply_user(&mut u, val)?;
                    g.owner = Some(Box::new(u));
                }
            },
            "members" => match val {
                JVal::Null => g.members = None,
                JVal::Arr(a) => {
                    let mut out = Vec::with_capacity(a.len());
                    for e in a {
                        out.push(user_from_json(e)?);
                    }
                    g.members = Some(out);
                }
                _ => return Err(DeErr),
            },
            "roles" => g.roles = roles_from_json(val)?,
            other if IGNORED.contains(&other) => {}
            _ => return Err(DeErr),
        }
    }
    Ok(())
}

pub fn apply_extent(e: &mut Extent, v: &JVal) -> Result<(), DeErr> {
    let o = obj(v)?;
    for (k, val) in o.iter() {
        match k.as_str() {
            "id" => e.id = jint(val)?,
            "lowerLeft" => e.lower_left = jpoint(val)?,
            "upperRight" => e.upper_right = jpoint(val)?,
            other if IGNORED.contains(&other) => {}
            _ => return Err(DeErr),
        }
    }
    Ok(())
}

pub fn extent_from_json(v: &JVal) -> Result<Extent, DeErr> {
    let mut e = Extent::default();
    apply_extent(&mut e, v)?;
    Ok(e)
}

pub fn apply_tile_grid(t: &mut TileGrid, v: &JVal) -> Result<(), DeErr> {
    let o = obj(v)?;
    for (k, val) in o.iter() {
        match k.as_str() {
            "id" => t.id = jint(val)?,
            "type" => t.typ = jstr(val)?,
            "tileGridOrigin" => t.origin = jpoint(val)?,
            "tileGridExtent" => match val {
                JVal::Null => t.extent = None,
                _ => {
                    let mut e = Extent::default();
                    apply_extent(&mut e, val)?;
                    t.extent = Some(Box::new(e));
                }
            },
            "tileSize" => t.tile_size = jint(val)?,
            "tileGridResolutions" => match val {
                JVal::Null => t.resolutions = None,
                JVal::Arr(a) => {
                    let mut out = Vec::with_capacity(a.len());
                    for e in a {
                        out.push(jdouble(e)?.ok_or(DeErr)?);
                    }
                    t.resolutions = Some(out);
                }
                _ => return Err(DeErr),
            },
            "matrixIds" if t.is_wmts => match val {
                JVal::Null => t.matrix_ids = None,
                JVal::Arr(a) => {
                    let mut out = Vec::with_capacity(a.len());
                    for e in a {
                        match e {
                            JVal::Null => out.push(None),
                            other => out.push(Some(jstr(other)?.ok_or(DeErr)?)),
                        }
                    }
                    t.matrix_ids = Some(out.into_iter().flatten().collect());
                    if a.iter().any(|e| matches!(e, JVal::Null)) {
                        t.has_null_matrix_ids = true;
                    }
                }
                _ => return Err(DeErr),
            },
            other if IGNORED.contains(&other) => {}
            _ => return Err(DeErr),
        }
    }
    Ok(())
}

pub fn tile_grid_from_json(v: &JVal, wmts: bool) -> Result<TileGrid, DeErr> {
    let mut t = if wmts { TileGrid::new_wmts_default() } else { TileGrid::default() };
    apply_tile_grid(&mut t, v)?;
    Ok(t)
}

pub fn apply_layer_appearance(a: &mut LayerAppearance, v: &JVal) -> Result<(), DeErr> {
    let o = obj(v)?;
    for (k, val) in o.iter() {
        match k.as_str() {
            "id" => a.id = jint(val)?,
            "attribution" => a.attribution = jstr(val)?,
            "hoverable" => a.hoverable = jbool(val)?,
            "clickable" => a.clickable = jbool(val)?,
            "hoverTemplate" => a.hover_template = jstr(val)?,
            "properties" => match val {
                JVal::Null => a.properties = None,
                JVal::Obj(m) => {
                    let mut out = Vec::with_capacity(m.len());
                    for (pk, pv) in m.iter() {
                        // Map<String,Object>: any JSON value is accepted;
                        // non-scalars are persisted via their toString.
                        out.push((pk.clone(), pv.clone()));
                    }
                    a.properties = Some(out);
                }
                _ => return Err(DeErr),
            },
            "name" => a.name = jstr(val)?,
            "maxResolution" => a.max_resolution = jdouble(val)?,
            "minResolution" => a.min_resolution = jdouble(val)?,
            "opacity" => a.opacity = jdouble(val)?,
            "visible" => a.visible = jbool(val)?,
            other if IGNORED.contains(&other) => {}
            _ => return Err(DeErr),
        }
    }
    Ok(())
}

pub fn appearance_from_json(v: &JVal) -> Result<LayerAppearance, DeErr> {
    let mut a = LayerAppearance::default();
    apply_layer_appearance(&mut a, v)?;
    Ok(a)
}

/// Deserialization of the *abstract* `LayerDataSource`: any non-null JSON
/// value fails ("no Creators ... abstract types").
pub fn apply_layer(l: &mut Layer, v: &JVal) -> Result<(), DeErr> {
    let o = obj(v)?;
    for (k, val) in o.iter() {
        match k.as_str() {
            "id" => l.id = jint(val)?,
            "name" => l.name = jstr(val)?,
            "description" => l.description = jstr(val)?,
            "source" => match val {
                JVal::Null => l.source = None,
                _ => return Err(DeErr), // abstract LayerDataSource
            },
            "appearance" => match val {
                JVal::Null => l.appearance = None,
                _ => {
                    let mut a = LayerAppearance::default();
                    apply_layer_appearance(&mut a, val)?;
                    l.appearance = Some(Box::new(a));
                }
            },
            other if IGNORED.contains(&other) => {}
            _ => return Err(DeErr),
        }
    }
    Ok(())
}

pub fn layer_from_json(v: &JVal) -> Result<Layer, DeErr> {
    let mut l = Layer::default();
    apply_layer(&mut l, v)?;
    Ok(l)
}

/// Apply JSON to a *concrete* layer data source (used by PUT, where
/// `readerForUpdating` is typed with the runtime class of the loaded
/// entity). The kind must already be set on `d`.
pub fn apply_layer_data_source(d: &mut LayerDataSource, v: &JVal) -> Result<(), DeErr> {
    let o = obj(v)?;
    let kind = d.kind();
    for (k, val) in o.iter() {
        // base fields
        match k.as_str() {
            "id" => {
                d.base.id = jint(val)?;
                continue;
            }
            "name" => {
                d.base.name = jstr(val)?;
                continue;
            }
            "type" => {
                d.base.typ = jstr(val)?;
                continue;
            }
            "url" => {
                d.base.url = jstr(val)?;
                continue;
            }
            "format" => {
                d.base.format = jstr(val)?;
                continue;
            }
            "tileGrid" => {
                match kind {
                    DsKind::TileWms => {
                        let f = d.tile_wms.as_mut().expect("tilewms fields");
                        match val {
                            JVal::Null => f.tile_grid = None,
                            _ => {
                                let wmts = tilegrid_json_is_wmts(val);
                                f.tile_grid = Some(Box::new(tile_grid_from_json(val, wmts)?));
                            }
                        }
                    }
                    DsKind::Wmts => {
                        let f = d.wmts.as_mut().expect("wmts fields");
                        match val {
                            JVal::Null => f.tile_grid = None,
                            _ => {
                                f.tile_grid = Some(Box::new(tile_grid_from_json(val, true)?));
                            }
                        }
                    }
                    _ => return Err(DeErr),
                }
                continue;
            }
            "version" => {
                match kind {
                    DsKind::ImageWms | DsKind::TileWms => {
                        d.image_wms.as_mut().expect("imagewms fields").version = jstr(val)?;
                    }
                    DsKind::Wfs => {
                        d.wfs.as_mut().expect("wfs fields").version = jstr(val)?;
                    }
                    _ => return Err(DeErr),
                }
                continue;
            }
            _ => {}
        }
        // subtype fields
        match (kind, k.as_str()) {
            (DsKind::ImageWms | DsKind::TileWms, "width") => {
                d.image_wms.as_mut().expect("imagewms fields").width = jint_prim(val)?;
            }
            (DsKind::ImageWms | DsKind::TileWms, "height") => {
                d.image_wms.as_mut().expect("imagewms fields").height = jint_prim(val)?;
            }
            (DsKind::ImageWms | DsKind::TileWms, "layerNames") => {
                d.image_wms.as_mut().expect("imagewms fields").layer_names = jstr(val)?;
            }
            (DsKind::ImageWms | DsKind::TileWms, "layerStyles") => {
                d.image_wms.as_mut().expect("imagewms fields").layer_styles = jstr(val)?;
            }
            (DsKind::ImageWms | DsKind::TileWms, "requestableByPath") => {
                d.image_wms.as_mut().expect("imagewms fields").requestable_by_path = jbool(val)?;
            }
            (DsKind::ImageWms | DsKind::TileWms, "customRequestPath") => {
                d.image_wms.as_mut().expect("imagewms fields").custom_request_path = jstr(val)?;
            }
            (DsKind::TileWms, "requestWithTiled") => {
                d.tile_wms.as_mut().expect("tilewms fields").request_with_tiled = jbool(val)?;
            }
            (DsKind::Wfs, "typeName") => {
                d.wfs.as_mut().expect("wfs fields").type_name = jstr(val)?;
            }
            (DsKind::Wfs, "typeNames") => {
                d.wfs.as_mut().expect("wfs fields").type_names = jstr(val)?;
            }
            (DsKind::Wmts, "urls") => match val {
                JVal::Null => d.wmts.as_mut().expect("wmts fields").urls = None,
                JVal::Arr(a) => {
                    let mut out = Vec::with_capacity(a.len());
                    for e in a {
                        match e {
                            JVal::Null => out.push(None),
                            other => out.push(jstr(other)?),
                        }
                    }
                    d.wmts.as_mut().expect("wmts fields").urls = Some(out.into_iter().flatten().collect());
                    if a.iter().any(|e| matches!(e, JVal::Null)) {
                        d.wmts.as_mut().expect("wmts fields").has_null_urls = true;
                    }
                }
                _ => return Err(DeErr),
            },
            (DsKind::Wmts, "wmtsLayer") => {
                d.wmts.as_mut().expect("wmts fields").wmts_layer = jstr(val)?;
            }
            (DsKind::Wmts, "wmtsStyle") => {
                d.wmts.as_mut().expect("wmts fields").wmts_style = jstr(val)?;
            }
            (DsKind::Wmts, "projection") => {
                d.wmts.as_mut().expect("wmts fields").projection = jstr(val)?;
            }
            (DsKind::Wmts, "matrixSet") => {
                d.wmts.as_mut().expect("wmts fields").matrix_set = jstr(val)?;
            }
            (DsKind::Wmts, "requestEncoding") => {
                d.wmts.as_mut().expect("wmts fields").request_encoding = jstr(val)?;
            }
            (DsKind::Wmts, "capabilitiesUrl") => {
                d.wmts.as_mut().expect("wmts fields").capabilities_url = jstr(val)?;
            }
            (DsKind::Xyz, "center") => {
                d.xyz.as_mut().expect("xyz fields").center = jpoint(val)?;
            }
            (DsKind::Xyz, "extent") => match val {
                JVal::Null => d.xyz.as_mut().expect("xyz fields").extent = None,
                _ => {
                    let mut e = Extent::default();
                    apply_extent(&mut e, val)?;
                    d.xyz.as_mut().expect("xyz fields").extent = Some(Box::new(e));
                }
            },
            (DsKind::Xyz, "resolutions") => match val {
                JVal::Null => d.xyz.as_mut().expect("xyz fields").resolutions = None,
                JVal::Arr(a) => {
                    let mut out: Vec<Option<f64>> = Vec::with_capacity(a.len());
                    for e in a {
                        out.push(jdouble(e)?);
                    }
                    d.xyz.as_mut().expect("xyz fields").resolutions = Some(out);
                }
                _ => return Err(DeErr),
            },
            (DsKind::Xyz, "tileSize") => {
                d.xyz.as_mut().expect("xyz fields").tile_size = jint(val)?;
            }
            (_, other) => {
                if IGNORED.contains(&other) {
                    // silently ignored
                } else {
                    return Err(DeErr);
                }
            }
        }
    }
    Ok(())
}

/// The concrete tile grid type referenced in a layer data source PUT:
/// WMTS data sources map to `WmtsTileGrid`, everything else to `TileGrid`.
/// (For TileWMS the declared property type is `TileGrid`; a `matrixIds`
/// key would be rejected there.)
fn tilegrid_json_is_wmts(v: &JVal) -> bool {
    match v {
        JVal::Obj(o) => o.iter().any(|(k, _)| k == "matrixIds"),
        _ => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::json::parse;

    #[test]
    fn user_apply() {
        let v = parse(br#"{"id":null,"firstName":"A","active":true,"userGroups":[5,"6"],"created":"x","userPermissions":{}}"#).unwrap();
        let mut u = User::default();
        apply_user(&mut u, &v).unwrap();
        assert_eq!(u.first_name, Some("A".into()));
        assert!(u.active);
        assert_eq!(u.user_groups, Some(vec![5, 6]));
        assert_eq!(u.roles, Some(vec![]));
    }

    #[test]
    fn unknown_field_rejected() {
        let v = parse(br#"{"nope":1}"#).unwrap();
        let mut u = User::default();
        assert!(apply_user(&mut u, &v).is_err());
        let mut r = Role::default();
        assert!(apply_role(&mut r, &parse(br#"{"accountName":"x"}"#).unwrap()).is_err());
    }

    #[test]
    fn layer_source_abstract() {
        let v = parse(br#"{"name":"L","source":{"id":12}}"#).unwrap();
        let mut l = Layer::default();
        assert!(apply_layer(&mut l, &v).is_err());
        let v = parse(br#"{"name":"L","source":null}"#).unwrap();
        assert!(apply_layer(&mut l, &v).is_ok());
    }

    #[test]
    fn tilewms_put_shape() {
        let v = parse(br#"{"id":12,"url":"http://u","tileGrid":{"type":"TileGrid","tileGridOrigin":{"x":1.5,"y":2.5},"tileSize":512,"tileGridResolutions":[1.5,2.5]}}"#).unwrap();
        let mut d = LayerDataSource::new_of_kind(DsKind::TileWms);
        apply_layer_data_source(&mut d, &v).unwrap();
        assert_eq!(d.base.id, Some(12));
        let f = d.tile_wms.as_ref().unwrap();
        assert_eq!(f.request_with_tiled, Some(true));
        let tg = f.tile_grid.as_ref().unwrap();
        assert_eq!(tg.typ, Some("TileGrid".into()));
        assert_eq!(tg.origin, Some((1.5, 2.5)));
        assert_eq!(tg.tile_size, Some(512));
        assert_eq!(tg.resolutions, Some(vec![1.5, 2.5]));
        assert!(!tg.is_wmts);
        // unknown (per-subtype) field rejected
        let v = parse(br#"{"id":12,"matrixSet":"x"}"#).unwrap();
        assert!(apply_layer_data_source(&mut d, &v).is_err());
    }

    #[test]
    fn date_validation() {
        assert!(valid_iso_date("1990-01-31"));
        assert!(!valid_iso_date("1990-02-31"));
        assert!(valid_iso_date("2000-02-29"));
        assert!(!valid_iso_date("1900-02-29"));
        assert!(!valid_iso_date("1990-1-1"));
    }
}

