{"content":"//! Database repository: entity loading (mirroring Hibernate's eager
//! `FetchMode.JOIN` graphs) and the write plans for create/update/delete,
//! including the `@Cascade(SAVE_UPDATE)` behaviour of layers' appearance
//! and tile grids, join-table replacement semantics and the
//! `LayerService.delete` map cleanup.

use crate::de::DeErr;
use crate::javaser;
use crate::json::JVal;
use crate::model::*;
use tokio_postgres::types::ToSql;
use tokio_postgres::Row;

pub type R<T> = Result<T, tokio_postgres::Error>;

/// Errors of a write operation. All of them make the caller answer with
/// the endpoint's error status (400 for POST, 404 for PUT/DELETE), exactly
/// as the original, whose controller catches any RuntimeException.
#[derive(Debug)]
pub enum WriteErr {
    Db(tokio_postgres::Error),
    /// TransientObjectException: reference to an instance without id.
    Transient,
    /// StaleObjectException: UPDATE of a row that does not exist.
    Stale,
    /// NonUniqueObjectException: same id already associated with the session.
    NonUnique,
}

impl From<tokio_postgres::Error> for WriteErr {
    fn from(e: tokio_postgres::Error) -> Self {
        WriteErr::Db(e)
    }
}

pub type WR<T> = Result<T, WriteErr>;

/// The entity identities "associated with the session" after the initial
/// `findById` of a PUT request; the cascade conflict checks use these.
#[derive(Debug, Default, Clone)]
pub struct SessionIds {
    pub appearances: Vec<i32>,
    pub tilegrids: Vec<i32>,
    pub extents: Vec<i32>,
}

impl SessionIds {
    fn of_layer(l: &Layer) -> SessionIds {
        let mut s = SessionIds::default();
        if let Some(a) = &l.appearance {
            s.appearances.push(a.id.unwrap_or(0));
        }
        if let Some(src) = &l.source {
            collect_ds(&mut s, src);
        }
        s
    }

    fn of_datasource(d: &LayerDataSource) -> SessionIds {
        let mut s = SessionIds::default();
        collect_ds(&mut s, d);
        s
    }

    fn of_appearance() -> SessionIds {
        SessionIds::default()
    }
}

fn collect_ds(s: &mut SessionIds, d: &LayerDataSource) {
    match d.kind() {
        DsKind::TileWms => {
            if let Some(f) = &d.tile_wms {
                if let Some(tg) = &f.tile_grid {
                    s.tilegrids.push(tg.id.unwrap_or(0));
                    if let Some(e) = &tg.extent {
                        s.extents.push(e.id.unwrap_or(0));
                    }
                }
            }
        }
        DsKind::Wmts => {
            if let Some(f) = &d.wmts {
                if let Some(tg) = &f.tile_grid {
                    s.tilegrids.push(tg.id.unwrap_or(0));
                    if let Some(e) = &tg.extent {
                        s.extents.push(e.id.unwrap_or(0));
                    }
                }
            }
        }
        DsKind::Xyz => {
            if let Some(f) = &d.xyz {
                if let Some(e) = &f.extent {
                    s.extents.push(e.id.unwrap_or(0));
                }
            }
        }
        _ => {}
    }
}

// ------------------------------------------------------------ PropertyValue

/// `PropertyValueConverter.convertToEntityAttribute`: string from the DB to
/// the best matching JSON type.
pub fn property_from_db(s: &str) -> JVal {
    if s.eq_ignore_ascii_case("true") {
        return JVal::Bool(true);
    }
    if s.eq_ignore_ascii_case("false") {
        return JVal::Bool(false);
    }
    if is_parsable(s) {
        let digits = |x: &str| !x.is_empty() && x.bytes().all(|b| b.is_ascii_digit());
        if digits(s) || (s.starts_with('-') && digits(&s[1..])) {
            if let Ok(v) = s.parse::<i64>() {
                return JVal::Int(v);
            }
        } else if let Ok(v) = s.parse::<f64>() {
            return JVal::Float(v);
        }
    }
    JVal::Str(s.to_string())
}

/// commons-lang3 `NumberUtils.isParsable`.
pub fn is_parsable(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    let b = s.as_bytes();
    let start = if b[0] == b'-' {
        if b.len() == 1 {
            return false;
        }
        1
    } else {
        0
    };
    let mut points = 0;
    for &c in &b[start..] {
        if c == b'.' {
            points += 1;
            if points > 1 {
                return false;
            }
        } else if !c.is_ascii_digit() {
            return false;
        }
    }
    true
}

/// `attribute.toString()` for a deserialized JSON property value
/// (Java `Object.toString` of String/Long/Double/Boolean/LinkedHashMap...).
pub fn property_to_db(v: &JVal) -> String {
    match v {
        JVal::Null => "null".to_string(),
        JVal::Bool(b) => b.to_string(),
        JVal::Int(i) => i.to_string(),
        JVal::Float(f) => crate::json::java_double(*f),
        JVal::Str(s) => s.clone(),
        JVal::Arr(a) => {
            let mut out = String::from("[");
            for (i, e) in a.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                out.push_str(&property_to_db(e));
            }
            out.push(']');
            out
        }
        JVal::Obj(o) => {
            let mut out = String::from("{");
            for (i, (k, e)) in o.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                out.push_str(k);
                out.push('=');
                out.push_str(&property_to_db(e));
            }
            out.push('}');
            out
        }
    }
}

// ------------------------------------------------------------------ loaders

fn role_of(row: &Row) -> Role {
    Role {
        id: Some(row.get(0)),
        name: row.get(1),
        description: row.get(2),
    }
}

pub async fn load_role(client: &tokio_postgres::Client, id: i32) -> R<Option<Role>> {
    let rows = client
        .query("SELECT id, name, description FROM roles WHERE id = $1", &[&id])
        .await?;
    Ok(rows.first().map(|r| role_of(r)))
}

pub async fn load_roles(client: &tokio_postgres::Client, ids: &[i32]) -> R<Vec<Role>> {
    let mut out = Vec::new();
    for id in ids {
        if let Some(r) = load_role(client, *id).await? {
            out.push(r);
        }
    }
    Ok(out)
}

pub async fn load_user(client: &tokio_postgres::Client, id: i32) -> R<Option<User>> {
    let rows = client
        .query(
            "SELECT p.id, p.firstname, p.lastname, p.email, to_char(p.birthday, 'YYYY-MM-DD'), \
             p.language, u.accountname, u.active, u.password \
             FROM persons p JOIN users u ON u.id = p.id WHERE p.id = $1",
            &[&id],
        )
        .await?;
    let row = match rows.first() {
        Some(r) => r,
        None => return Ok(None),
    };
    let mut u = User {
        id: Some(row.get(0)),
        first_name: row.get(1),
        last_name: row.get(2),
        email: row.get(3),
        birthday: row.get(4),
        language: row.get(5),
        account_name: row.get(6),
        password: row.get(8),
        active: row.get::<usize, bool>(7),
        ..User::default()
    };
    let role_ids: Vec<i32> = client
        .query(
            "SELECT r.id FROM roles r JOIN users_roles ur ON ur.role_id = r.id \
             WHERE ur.user_id = $1 ORDER BY r.id",
            &[&id],
        )
        .await?
        .iter()
        .map(|r| r.get(0))
        .collect();
    u.roles = Some(load_roles(client, &role_ids).await?);
    let gids: Vec<i32> = client
        .query(
            "SELECT usergroup_id FROM user_usergroup WHERE user_id = $1 ORDER BY usergroup_id",
            &[&id],
        )
        .await?
        .iter()
        .map(|r| r.get(0))
        .collect();
    u.user_groups = Some(gids);
    Ok(Some(u))
}

pub async fn load_group(client: &tokio_postgres::Client, id: i32) -> R<Option<UserGroup>> {
    let rows = client
        .query("SELECT id, name, owner_id FROM usergroups WHERE id = $1", &[&id])
        .await?;
    let row = match rows.first() {
        Some(r) => r,
        None => return Ok(None),
    };
    let mut g = UserGroup {
        id: Some(row.get(0)),
        name: row.get(1),
        owner: None,
        members: Some(Vec::new()),
        roles: Some(Vec::new()),
    };
    let owner_id: Option<i32> = row.get(2);
    if let Some(oid) = owner_id {
        g.owner = load_user(client, oid).await?.map(Box::new);
    }
    let member_ids: Vec<i32> = client
        .query(
            "SELECT user_id FROM user_usergroup WHERE usergroup_id = $1 ORDER BY user_id",
            &[&id],
        )
        .await?
        .iter()
        .map(|r| r.get(0))
        .collect();
    let mut members = Vec::new();
    for mid in member_ids {
        if let Some(u) = load_user(client, mid).await? {
            members.push(u);
        }
    }
    g.members = Some(members);
    let role_ids: Vec<i32> = client
        .query(
            "SELECT r.id FROM roles r JOIN usergroups_roles gr ON gr.role_id = r.id \
             WHERE gr.usergroup_id = $1 ORDER BY r.id",
            &[&id],
        )
        .await?
        .iter()
        .map(|r| r.get(0))
        .collect();
    g.roles = Some(load_roles(client, &role_ids).await?);
    Ok(Some(g))
}

pub async fn load_extent(client: &tokio_postgres::Client, id: i32) -> R<Option<Extent>> {
    let rows = client
        .query(
            "SELECT id, lowerleft_x, lowerleft_y, upperright_x, upperright_y FROM extents WHERE id = $1",
            &[&id],
        )
        .await?;
    Ok(rows.first().map(|r| Extent {
        id: Some(r.get(0)),
        lower_left: match r.get::<_, Option<f64>>(1) {
            Some(x) => Some((x, r.get(2))),
            None => None,
        },
        upper_right: match r.get::<_, Option<f64>>(3) {
            Some(x) => Some((x, r.get(4))),
            None => None,
        },
    }))
}

pub async fn load_tile_grid(client: &tokio_postgres::Client, id: i32) -> R<Option<TileGrid>> {
    let rows = client
        .query(
            "SELECT t.id, t.type, t.tilegridorigin_x, t.tilegridorigin_y, t.tilesize, \
             t.tilegridextent_id, (w.id IS NOT NULL) \
             FROM tilegrids t LEFT JOIN wmtstilegrids w ON w.id = t.id WHERE t.id = $1",
            &[&id],
        )
        .await?;
    let row = match rows.first() {
        Some(r) => r,
        None => return Ok(None),
    };
    let mut t = TileGrid {
        id: Some(row.get(0)),
        typ: row.get(1),
        origin: match row.get::<_, Option<f64>>(2) {
            Some(x) => Some((x, row.get(3))),
            None => None,
        },
        tile_size: row.get(4),
        extent: None,
        resolutions: None,
        matrix_ids: None,
        is_wmts: row.get(6),
        has_null_matrix_ids: false,
    };
    let ext_id: Option<i32> = row.get(5);
    if let Some(eid) = ext_id {
        t.extent = load_extent(client, eid).await?.map(Box::new);
    }
    let res: Vec<f64> = client
        .query(
            "SELECT resolution FROM tilegrid_resolution WHERE tilegrid_id = $1 ORDER BY idx",
            &[&id],
        )
        .await?
        .iter()
        .map(|r| r.get(0))
        .collect();
    t.resolutions = Some(res);
    if t.is_wmts {
        let mids: Vec<String> = client
            .query(
                "SELECT matrixids FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1",
                &[&id],
            )
            .await?
            .iter()
            .map(|r| r.get(0))
            .collect();
        t.matrix_ids = Some(mids);
    }
    Ok(Some(t))
}

const DS_SELECT: &str = "SELECT l.id, l.name, l.type, l.url, l.format, \
    i.width, i.height, i.version, i.layernames, i.layerstyles, i.requestablebypath, i.customrequestpath, \
    t.tilegrid_id, t.request_with_tiled, \
    w.version, w.typename, w.typenames, \
    m.tilegrid_id, m.wmtslayer, m.wmtsstyle, m.projection, m.matrixset, m.requestencoding, m.capabilitiesurl, \
    x.center_x, x.center_y, x.extent_id, x.tilesize, \
    (t.id IS NOT NULL) AS is_tilewms, (i.id IS NOT NULL) AS is_imagewms, \
    (w.id IS NOT NULL) AS is_wfs, (m.id IS NOT NULL) AS is_wmts, (x.id IS NOT NULL) AS is_xyz \
    FROM layerdatasources l \
    LEFT JOIN imagewmslayerdatasources i ON i.id = l.id \
    LEFT JOIN tilewmslayerdatasources t ON t.id = l.id \
    LEFT JOIN wfslayerdatasources w ON w.id = l.id \
    LEFT JOIN wmtslayerdatasources m ON m.id = l.id \
    LEFT JOIN xyzlayerdatasources x ON x.id = l.id";

fn ds_kind_of(row: &Row) -> Option<DsKind> {
    if row.get::<_, bool>(28) {
        Some(DsKind::TileWms)
    } else if row.get::<_, bool>(29) {
        Some(DsKind::ImageWms)
    } else if row.get::<_, bool>(30) {
        Some(DsKind::Wfs)
    } else if row.get::<_, bool>(31) {
        Some(DsKind::Wmts)
    } else if row.get::<_, bool>(32) {
        Some(DsKind::Xyz)
    } else {
        None
    }
}

pub async fn load_data_source(
    client: &tokio_postgres::Client,
    id: i32,
) -> R<Option<LayerDataSource>> {
    let rows = client
        .query(&format!("{} WHERE l.id = $1", DS_SELECT), &[&id])
        .await?;
    let row = match rows.first() {
        Some(r) => r,
        None => return Ok(None),
    };
    let kind = match ds_kind_of(row) {
        Some(k) => k,
        // row without any subtype table entry: Hibernate cannot build an
        // instance of the abstract class either; treat as absent.
        None => return Ok(None),
    };
    let mut d = LayerDataSource::new_of_kind(kind);
    d.base = DsBase {
        id: Some(row.get(0)),
        name: row.get(1),
        typ: row.get(2),
        url: row.get(3),
        format: row.get(4),
    };
    match kind {
        DsKind::ImageWms | DsKind::TileWms => {
            let im = ImageWmsFields {
                width: row.get(5),
                height: row.get(6),
                version: row.get(7),
                layer_names: row.get(8),
                layer_styles: row.get(9),
                requestable_by_path: row.get(10),
                custom_request_path: row.get(11),
            };
            d.image_wms = Some(im);
            if kind == DsKind::TileWms {
                let mut tw = TileWmsFields {
                    tile_grid: None,
                    request_with_tiled: row.get(13),
                };
                let tg_id: Option<i32> = row.get(12);
                if let Some(tid) = tg_id {
                    tw.tile_grid = load_tile_grid(client, tid).await?.map(Box::new);
                }
                d.tile_wms = Some(tw);
            }
        }
        DsKind::Wfs => {
            d.wfs = Some(WfsFields {
                version: row.get(14),
                type_name: row.get(15),
                type_names: row.get(16),
            });
        }
        DsKind::Wmts => {
            let mut wm = WmtsFields {
                tile_grid: None,
                urls: None,
                wmts_layer: row.get(19),
                wmts_style: row.get(20),
                projection: row.get(21),
                matrix_set: row.get(22),
                request_encoding: row.get(23),
                capabilities_url: row.get(24),
                has_null_urls: false,
            };
            let tg_id: Option<i32> = row.get(18);
            if let Some(tid) = tg_id {
                let mut tg = load_tile_grid(client, tid).await?.unwrap_or_else(|| {
                    let mut tg = TileGrid::new_wmts_default();
                    tg.id = Some(tid);
                    tg
                });
                tg.is_wmts = true;
                wm.tile_grid = Some(Box::new(tg));
            }
            let urls: Vec<String> = client
                .query(
                    "SELECT urls FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1",
                    &[&id],
                )
                .await?
                .iter()
                .map(|r| r.get(0))
                .collect();
            wm.urls = Some(urls);
            d.wmts = Some(wm);
        }
        DsKind::Xyz => {
            let mut xf = XyzFields {
                center: match row.get::<_, Option<f64>>(25) {
                    Some(x) => Some((x, row.get(26))),
                    None => None,
                },
                extent: None,
                resolutions: Some(Vec::new()),
                tile_size: row.get(28 - 4),
            };
            // note: tilesize sits at index 27; fix below
            let tile_size: Option<i32> = row.get(27);
            let _ = row.get::<_, Option<i32>>(28 - 1);
            xf.tile_size = tile_size;
            let ext_id: Option<i32> = row.get(27 - 0 - 0);
            let _ = &ext_id;
            // re-read precisely
            let ext_id: Option<i32> = row.get(27 - 1);
            if let Some(eid) = row.get::<_, Option<i32>>(27) {
                let _ = eid;
            }
            let real_ext: Option<i32> = row.get(27 - 1 + 1);
            if let Some(eid) = real_ext {
                xf.extent = load_extent(client, eid).await?.map(Box::new);
            }
            let bytes: Vec<Vec<u8>> = client
                .query(
                    "SELECT resolution FROM xyzlayerdatasrc_resolution \
                     WHERE xyzlayerdatasrc_id = $1 ORDER BY idx",
                    &[&id],
                )
                .await?
                .iter()
                .map(|r| r.get(0))
                .collect();
            let mut res: Vec<Option<f64>> = Vec::with_capacity(bytes.len());
            for b in &bytes {
                match javaser::decode_value(b) {
                    Ok(v) => res.push(v),
                    Err(()) => return Err(corrupt_resolution()),
                }
            }
            xf.resolutions = Some(res);
            d.xyz = Some(xf);
        }
    }
    Ok(Some(d))
}

fn corrupt_resolution() -> tokio_postgres::Error {
    // The original throws a StreamCorruptedException while lazily loading
    // the element collection, which ends as a 500.
    tokio_postgres::Error::io(std::io::Error::new(
        std::io::ErrorKind::InvalidData,
        "corrupt java-serialized resolution",
    ))
}

pub async fn load_appearance(
