// ------------------------------------------------------------------ filter

/// Column mapping for the `/filter` endpoint per resource.
fn filter_column(resource: &str, field: &str) -> Option<&'static str> {
    let fields = restrictable_fields(resource);
    let f = fields.iter().find(|f| f.eq_ignore_ascii_case(field))?;
    Some(match (resource, f.as_ref()) {
        ("users", "id") => "p.id",
        ("users", "firstName") => "p.firstname",
        ("users", "lastName") => "p.lastname",
        ("users", "email") => "p.email",
        ("users", "accountName") => "u.accountname",
        ("users", "password") => "u.password",
        ("users", "active") => "u.active",
        ("groups", "id") => "id",
        ("groups", "name") => "name",
        ("roles", "id") => "id",
        ("roles", "name") => "name",
        ("roles", "description") => "description",
        ("layers", "id") => "id",
        ("layers", "name") => "name",
        ("layers", "description") => "description",
        ("layerdatasources", "id") => "id",
        ("layerdatasources", "name") => "name",
        ("layerdatasources", "type") => "type",
        ("layerdatasources", "url") => "url",
        ("layerdatasources", "format") => "format",
        ("layerappearances", "id") => "id",
        ("layerappearances", "attribution") => "attribution",
        ("layerappearances", "hoverable") => "hoverable",
        ("layerappearances", "clickable") => "clickable",
        ("layerappearances", "hoverTemplate") => "hovertemplate",
        ("layerappearances", "name") => "name",
        ("layerappearances", "maxResolution") => "maxresolution",
        ("layerappearances", "minResolution") => "minresolution",
        ("layerappearances", "opacity") => "opacity",
        ("layerappearances", "visible") => "visible",
        _ => return None,
    })
}

pub struct FilterGroup {
    pub field: String,
    pub values: Vec<FilterVal>,
}

/// Resolve the filter request into per-field groups of casted values.
/// Returns the groups actually usable (unknown field names are dropped);
/// an empty result means the original returns an empty list.
pub fn resolve_filters(resource: &str, params: &[(String, Vec<String>)]) -> Vec<FilterGroup> {
    let mut out: Vec<FilterGroup> = Vec::new();
    for (key, values) in params {
        if key.eq_ignore_ascii_case("output:only") {
            continue;
        }
        let ft = match filter_field_type(resource, key) {
            Some(ft) => ft,
            None => continue,
        };
        if filter_column(resource, key).is_none() {
            continue;
        }
        // canonical name
        let canon = restrictable_fields(resource)
            .iter()
            .find(|f| f.eq_ignore_ascii_case(key))
            .unwrap()
            .to_string();
        if let Some(existing) = out.iter_mut().find(|g| g.field == canon) {
            for v in values {
                existing.values.push(cast_filter_value(ft, v));
            }
        } else {
            out.push(FilterGroup {
                field: canon,
                values: values.iter().map(|v| cast_filter_value(ft, v)).collect(),
            });
        }
    }
    out
}

pub async fn filter_ids(
    client: &tokio_postgres::Client,
    resource: &str,
    groups: &[FilterGroup],
) -> R<Vec<i32>> {
    let mut params: Vec<Box<dyn ToSql + Sync>> = Vec::new();
    let mut wheres: Vec<String> = Vec::new();
    for g in groups {
        let col = filter_column(resource, &g.field).expect("checked column");
        let mut ors: Vec<String> = Vec::new();
        for v in &g.values {
            match v {
                FilterVal::None => {
                    // eq(field, null): never matches
                    ors.push("1 = 0".to_string());
                }
                FilterVal::Int(i) => {
                    let idx = params.len() + 1;
                    params.push(Box::new(*i));
                    ors.push(format!("{} = ${}", col, idx));
                }
                FilterVal::Str(s) => {
                    let idx = params.len() + 1;
                    params.push(Box::new(s.clone()));
                    ors.push(format!("{} = ${}", col, idx));
                }
                FilterVal::Bool(b) => {
                    let idx = params.len() + 1;
                    params.push(Box::new(*b));
                    ors.push(format!("{} = ${}", col, idx));
                }
                FilterVal::Double(f) => {
                    let idx = params.len() + 1;
                    params.push(Box::new(*f));
                    ors.push(format!("{} = ${}", col, idx));
                }
            }
        }
        if !ors.is_empty() {
            wheres.push(format!("({})", ors.join(" OR ")));
        }
    }
    let (base, root_alias) = match resource {
        "users" => (
            "SELECT p.id FROM persons p JOIN users u ON u.id = p.id",
            "p.id",
        ),
        "groups" => ("SELECT id FROM usergroups", "id"),
        "roles" => ("SELECT id FROM roles", "id"),
        "layers" => ("SELECT id FROM layers", "id"),
        "layerdatasources" => ("SELECT id FROM layerdatasources", "id"),
        "layerappearances" => ("SELECT id FROM layerappearances", "id"),
        _ => return Ok(Vec::new()),
    };
    let mut sql = String::from(base);
    if !wheres.is_empty() {
        sql.push_str(" WHERE ");
        sql.push_str(&wheres.join(" AND "));
    }
    sql.push_str(&format!(" ORDER BY {}", root_alias));
    let refs: Vec<&(dyn ToSql + Sync)> = params.iter().map(|p| p.as_ref()).collect();
    Ok(client.query(&sql, &refs).await?.iter().map(|r| r.get(0)).collect())
}

