pub async fn load_data_source(
    client: &tokio_postgres::Client,
    id: i32,
) -> R<Option<LayerDataSource>> {
    let rows = client
        .query(&format!("{} WHERE l.id = $1", DS_SELECT), &[&id])
        .await?;
    let row = match rows.first() {
        Some(r) => r,
        None => return Ok(None),
    };
    let kind = match ds_kind_of(row) {
        Some(k) => k,
        // A row without any subtype table entry: Hibernate cannot build an
        // instance of the abstract class either; treat it as absent.
        None => return Ok(None),
    };
    let mut d = LayerDataSource::new_of_kind(kind);
    d.base = DsBase {
        id: Some(row.get(0)),
        name: row.get(1),
        typ: row.get(2),
        url: row.get(3),
        format: row.get(4),
    };
    match kind {
        DsKind::ImageWms | DsKind::TileWms => {
            d.image_wms = Some(ImageWmsFields {
                width: row.get(5),
                height: row.get(6),
                version: row.get(7),
                layer_names: row.get(8),
                layer_styles: row.get(9),
                requestable_by_path: row.get(10),
                custom_request_path: row.get(11),
            });
            if kind == DsKind::TileWms {
                let mut tw = TileWmsFields {
                    tile_grid: None,
                    request_with_tiled: row.get(13),
                };
                let tg_id: Option<i32> = row.get(12);
                if let Some(tid) = tg_id {
                    tw.tile_grid = load_tile_grid(client, tid).await?.map(Box::new);
                }
                d.tile_wms = Some(tw);
            }
        }
        DsKind::Wfs => {
            d.wfs = Some(WfsFields {
                version: row.get(14),
                type_name: row.get(15),
                type_names: row.get(16),
            });
        }
        DsKind::Wmts => {
            let mut wm = WmtsFields {
                tile_grid: None,
                urls: None,
                wmts_layer: row.get(18),
                wmts_style: row.get(19),
                projection: row.get(20),
                matrix_set: row.get(21),
                request_encoding: row.get(22),
                capabilities_url: row.get(23),
                has_null_urls: false,
            };
            let tg_id: Option<i32> = row.get(17);
            if let Some(tid) = tg_id {
                let mut tg = load_tile_grid(client, tid)
                    .await?
                    .unwrap_or_else(|| TileGrid::new_wmts_default());
                tg.is_wmts = true;
                tg.id = Some(tid);
                wm.tile_grid = Some(Box::new(tg));
            }
            let urls: Vec<String> = client
                .query(
                    "SELECT urls FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1",
                    &[&id],
                )
                .await?
                .iter()
                .map(|r| r.get(0))
                .collect();
            wm.urls = Some(urls);
            d.wmts = Some(wm);
        }
        DsKind::Xyz => {
            let mut xf = XyzFields {
                center: match row.get::<_, Option<f64>>(24) {
                    Some(x) => Some((x, row.get(25))),
                    None => None,
                },
                extent: None,
                resolutions: Some(Vec::new()),
                tile_size: row.get(27),
            };
            if let Some(eid) = row.get::<_, Option<i32>>(26) {
                xf.extent = load_extent(client, eid).await?.map(Box::new);
            }
            let bytes: Vec<Vec<u8>> = client
                .query(
                    "SELECT resolution FROM xyzlayerdatasrc_resolution \
                     WHERE xyzlayerdatasrc_id = $1 ORDER BY idx",
                    &[&id],
                )
                .await?
                .iter()
                .map(|r| r.get(0))
                .collect();
            let mut res: Vec<Option<f64>> = Vec::with_capacity(bytes.len());
            for b in &bytes {
                match javaser::decode_value(b) {
                    Ok(v) => res.push(v),
                    Err(()) => return Err(corrupt_resolution()),
                }
            }
            xf.resolutions = Some(res);
            d.xyz = Some(xf);
        }
    }
    Ok(Some(d))
}

