                .await?;
            if n != 1 {
                return Err(WriteErr::Stale);
            }
            // the deserialized instance owns an initialized (empty) map:
            // existing property rows are replaced
            tx.execute(
                "DELETE FROM layerappearances_properties WHERE appearance_id = $1",
                &[&id],
            )
            .await?;
            if let Some(props) = &a.properties {
                for (k, v) in props {
                    let val = property_to_db(v);
                    tx.execute(
                        "INSERT INTO layerappearances_properties (appearance_id, property, value) VALUES ($1, $2, $3)",
                        &[&id, k, &val],
                    )
                    .await?;
                }
            }
            Ok(())
        }
    }
}

/// Insert or update a `Layer` root entity.
#[allow(clippy::too_many_arguments)]
pub async fn save_layer(
    tx: &Transaction<'_>,
    alloc: &tokio_postgres::Client,
    l: &mut Layer,
    sess: &SessionIds,
    sets: &Sets,
    is_new: bool,
) -> WR<()> {
    let layer_id = match l.id {
        Some(id) => id,
        None => {
            let id = crate::db::allocate_id(alloc).await.map_err(WriteErr::from_db)?;
            l.id = Some(id);
            id
        }
    };
    let mut appearance_id: Option<i32> = None;
    if sets.appearance {
        if let Some(a) = l.appearance.as_mut() {
            cascade_appearance(tx, alloc, a, sess).await?;
            appearance_id = a.id;
        }
    } else if let Some(a) = &l.appearance {
        appearance_id = a.id;
    }
    let source_id: Option<i32> = if sets.source { None } else { l.source.as_ref().and_then(|d| d.base.id) };
    if is_new {
        tx.execute(
            "INSERT INTO layers (id, created, modified, description, name, appearance_id, source_id) \
             VALUES ($1, now(), now(), $2, $3, $4, $5)",
            &[&layer_id, &l.name, &l.description, &appearance_id, &source_id],
        )
        .await?;
    } else {
        let n = tx
            .execute(
                "UPDATE layers SET modified = now(), description = $1, name = $2, appearance_id = $3, \
                 source_id = $4 WHERE id = $5",
                &[&l.description, &l.name, &appearance_id, &source_id, &layer_id],
            )
            .await?;
        if n != 1 {
            return Err(WriteErr::Stale);
        }
    }
    Ok(())
}

