/// Insert or update a `User` root entity (persons + users + join tables).
pub async fn save_user(
    tx: &Transaction<'_>,
    alloc: &tokio_postgres::Client,
    u: &mut User,
    sets: &Sets,
    is_new: bool,
) -> WR<()> {
    let id = match u.id {
        Some(id) => id,
        None => {
            let id = crate::db::allocate_id(alloc).await.map_err(WriteErr::from_db)?;
            u.id = Some(id);
            id
        }
    };
    if is_new {
        tx.execute(
            "INSERT INTO persons (id, created, modified, birthday, email, firstname, language, lastname) \
             VALUES ($1, now(), now(), CAST($2::text AS date), $3, $4, $5, $6)",
            &[&id, &u.birthday, &u.email, &u.first_name, &u.language, &u.last_name],
        )
        .await?;
        tx.execute(
            "INSERT INTO users (accountname, active, password, id) VALUES ($1, $2, $3, $4)",
            &[&u.account_name, &u.active, &u.password, &id],
        )
        .await?;
        if let Some(roles) = &u.roles {
            let ids = collect_role_ids(roles)?;
            for rid in dedup_i32(&ids) {
                tx.execute(
                    "INSERT INTO users_roles (user_id, role_id) VALUES ($1, $2)",
                    &[&id, &rid],
                )
                .await?;
            }
        }
        if let Some(groups) = &u.user_groups {
            for gid in dedup_i32(groups) {
                tx.execute(
                    "INSERT INTO user_usergroup (usergroup_id, user_id) VALUES ($1, $2)",
                    &[&gid, &id],
                )
                .await?;
            }
            if u.has_null_group_refs {
                tx.execute(
                    "INSERT INTO user_usergroup (usergroup_id, user_id) VALUES (NULL, $1)",
                    &[&id],
                )
                .await?;
            }
        }
    } else {
        let n = tx
            .execute(
                "UPDATE persons SET modified = now(), birthday = CAST($1::text AS date), email = $2, \
                 firstname = $3, language = $4, lastname = $5 WHERE id = $6",
                &[&u.birthday, &u.email, &u.first_name, &u.language, &u.last_name, &id],
            )
            .await?;
        if n != 1 {
            return Err(WriteErr::Stale);
        }
        tx.execute(
            "UPDATE users SET accountname = $1, active = $2, password = $3 WHERE id = $4",
            &[&u.account_name, &u.active, &u.password, &id],
        )
        .await?;
        if sets.roles {
            tx.execute("DELETE FROM users_roles WHERE user_id = $1", &[&id]).await?;
            if let Some(roles) = &u.roles {
                let ids = collect_role_ids(roles)?;
                for rid in dedup_i32(&ids) {
                    tx.execute(
                        "INSERT INTO users_roles (user_id, role_id) VALUES ($1, $2)",
                        &[&id, &rid],
                    )
                    .await?;
                }
            }
        }
        if sets.user_groups {
            tx.execute("DELETE FROM user_usergroup WHERE user_id = $1", &[&id]).await?;
            if let Some(groups) = &u.user_groups {
                for gid in dedup_i32(groups) {
                    tx.execute(
                        "INSERT INTO user_usergroup (usergroup_id, user_id) VALUES ($1, $2)",
                        &[&gid, &id],
                    )
                    .await?;
                }
                if u.has_null_group_refs {
                    tx.execute(
                        "INSERT INTO user_usergroup (usergroup_id, user_id) VALUES (NULL, $1)",
                        &[&id],
                    )
                    .await?;
                }
            }
        }
    }
    Ok(())
}

fn collect_role_ids(roles: &[Role]) -> Result<Vec<i32>, WriteErr> {
    let mut out = Vec::new();
    for r in roles {
        match r.id {
            Some(id) => out.push(id),
            None => return Err(WriteErr::Transient),
        }
    }
    Ok(out)
}

/// Insert or update a `UserGroup` root entity.
pub async fn save_group(
    tx: &Transaction<'_>,
    alloc: &tokio_postgres::Client,
    g: &mut UserGroup,
    sets: &Sets,
    is_new: bool,
) -> WR<()> {
    let id = match g.id {
        Some(id) => id,
        None => {
            let id = crate::db::allocate_id(alloc).await.map_err(WriteErr::from_db)?;
            g.id = Some(id);
            id
        }
    };
    let owner_id: Option<i32> = match g.owner.as_ref() {
        None => None,
        Some(o) => match o.id {
            Some(oid) => Some(oid),
            None => return Err(WriteErr::Transient),
        },
    };
    if is_new {
        tx.execute(
            "INSERT INTO usergroups (id, created, modified, name, owner_id) VALUES ($1, now(), now(), $2, $3)",
            &[&id, &g.name, &owner_id],
        )
        .await?;
        if let Some(members) = &g.members {
            let ids = collect_member_ids(members)?;
            for mid in dedup_i32(&ids) {
                tx.execute(
                    "INSERT INTO user_usergroup (usergroup_id, user_id) VALUES ($1, $2)",
                    &[&id, &mid],
                )
                .await?;
            }
        }
        if let Some(roles) = &g.roles {
            let ids = collect_role_ids(roles)?;
            for rid in dedup_i32(&ids) {
                tx.execute(
                    "INSERT INTO usergroups_roles (usergroup_id, role_id) VALUES ($1, $2)",
                    &[&id, &rid],
                )
                .await?;
            }
        }
    } else {
        let n = tx
            .execute(
                "UPDATE usergroups SET modified = now(), name = $1, owner_id = $2 WHERE id = $3",
                &[&g.name, &owner_id, &id],
            )
            .await?;
        if n != 1 {
            return Err(WriteErr::Stale);
        }
        if sets.owner && g.owner.is_none() {
            // "owner": null clears the reference; already written above
        }
        if sets.members {
            tx.execute("DELETE FROM user_usergroup WHERE usergroup_id = $1", &[&id]).await?;
            if let Some(members) = &g.members {
                let ids = collect_member_ids(members)?;
                for mid in dedup_i32(&ids) {
                    tx.execute(
                        "INSERT INTO user_usergroup (usergroup_id, user_id) VALUES ($1, $2)",
                        &[&id, &mid],
                    )
                    .await?;
                }
            }
        }
        if sets.group_roles {
            tx.execute("DELETE FROM usergroups_roles WHERE usergroup_id = $1", &[&id]).await?;
            if let Some(roles) = &g.roles {
                let ids = collect_role_ids(roles)?;
                for rid in dedup_i32(&ids) {
                    tx.execute(
                        "INSERT INTO usergroups_roles (usergroup_id, role_id) VALUES ($1, $2)",
                        &[&id, &rid],
                    )
                    .await?;
                }
            }
        }
    }
    Ok(())
}

fn collect_member_ids(members: &[User]) -> Result<Vec<i32>, WriteErr> {
    let mut out = Vec::new();
    for m in members {
        match m.id {
            Some(id) => out.push(id),
            None => return Err(WriteErr::Transient),
        }
    }
    Ok(out)
}

