                        cascade_tile_grid(tx, alloc, tg, sess).await?;
                        tg_id = tg.id;
                    }
                } else {
                    tg_id = tw.tile_grid.as_ref().and_then(|t| t.id);
                }
                tx.execute(
                    "UPDATE tilewmslayerdatasources SET request_with_tiled = $1, tilegrid_id = $2 WHERE id = $3",
                    &[&tw.request_with_tiled, &tg_id, &id],
                )
                .await?;
            }
        }
        DsKind::Wfs => {
            let w = d.wfs.as_ref().expect("wfs fields");
            tx.execute(
                "UPDATE wfslayerdatasources SET typename = $1, typenames = $2, version = $3 WHERE id = $4",
                &[&w.type_name, &w.type_names, &w.version, &id],
            )
            .await?;
        }
        DsKind::Wmts => {
            let wm = d.wmts.as_mut().expect("wmts fields");
            let mut tg_id: Option<i32> = None;
            if sets.tile_grid {
                if let Some(tg) = wm.tile_grid.as_mut() {
                    cascade_tile_grid(tx, alloc, tg, sess).await?;
                    tg_id = tg.id;
                }
            } else {
                tg_id = wm.tile_grid.as_ref().and_then(|t| t.id);
            }
            tx.execute(
                "UPDATE wmtslayerdatasources SET capabilitiesurl = $1, matrixset = $2, projection = $3, \
                 requestencoding = $4, wmtslayer = $5, wmtsstyle = $6, tilegrid_id = $7 WHERE id = $8",
                &[
                    &wm.capabilities_url,
                    &wm.matrix_set,
                    &wm.projection,
                    &wm.request_encoding,
                    &wm.wmts_layer,
                    &wm.wmts_style,
                    &tg_id,
                    &id,
                ],
            )
            .await?;
            if sets.urls {
                tx.execute(
                    "DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1",
                    &[&id],
                )
                .await?;
                if let Some(urls) = &wm.urls {
                    for u in urls {
                        tx.execute(
                            "INSERT INTO wmtslayerdatasources_urls (wmtslayerdatasources_id, urls) VALUES ($1, $2)",
                            &[&id, u],
                        )
                        .await?;
                    }
                    if wm.has_null_urls {
                        tx.execute(
                            "INSERT INTO wmtslayerdatasources_urls (wmtslayerdatasources_id, urls) VALUES ($1, NULL)",
                            &[&id],
                        )
                        .await?;
                    }
                }
            }
        }
        DsKind::Xyz => {
            let xf = d.xyz.as_mut().expect("xyz fields");
            let ext_id: Option<i32> = if sets.extent {
                match xf.extent.as_ref() {
                    None => None,
                    Some(e) => match e.id {
                        // no cascade on @OneToOne: transient refs fail
                        None => return Err(WriteErr::Transient),
                        Some(eid) => Some(eid),
                    },
                }
            } else {
                xf.extent.as_ref().and_then(|e| e.id)
            };
            let (cx, cy) = match xf.center {
                Some((x, y)) => (Some(x), Some(y)),
                None => (None, None),
            };
            tx.execute(
                "UPDATE xyzlayerdatasources SET center_x = $1, center_y = $2, tilesize = $3, extent_id = $4 WHERE id = $5",
                &[&cx, &cy, &xf.tile_size, &ext_id, &id],
            )
            .await?;
            if sets.resolutions {
                tx.execute(
                    "DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1",
                    &[&id],
                )
                .await?;
                if let Some(res) = &xf.resolutions {
                    for (i, r) in res.iter().enumerate() {
                        let idx = i as i32;
                        let bytes = match r {
                            Some(f) => javaser::encode_double(*f),
                            None => javaser::encode_null(),
                        };
                        tx.execute(
                            "INSERT INTO xyzlayerdatasrc_resolution (xyzlayerdatasrc_id, resolution, idx) VALUES ($1, $2, $3)",
                            &[&id, &bytes, &idx],
                        )
                        .await?;
                    }
                }
            }
        }
    }
    Ok(())
}

// ------------------------------------------------------------------ deletes

pub async fn delete_role_row(tx: &Transaction<'_>, id: i32) -> WR<()> {
    tx.execute("DELETE FROM roles WHERE id = $1", &[&id]).await?;
    Ok(())
}

pub async fn delete_user_rows(tx: &Transaction<'_>, id: i32) -> WR<()> {
    tx.execute("DELETE FROM users_roles WHERE user_id = $1", &[&id]).await?;
    tx.execute("DELETE FROM user_usergroup WHERE user_id = $1", &[&id]).await?;
    tx.execute("DELETE FROM users WHERE id = $1", &[&id]).await?;
    tx.execute("DELETE FROM persons WHERE id = $1", &[&id]).await?;
    Ok(())
}

pub async fn delete_group_rows(tx: &Transaction<'_>, id: i32) -> WR<()> {
    tx.execute("DELETE FROM user_usergroup WHERE usergroup_id = $1", &[&id]).await?;
    tx.execute("DELETE FROM usergroups_roles WHERE usergroup_id = $1", &[&id]).await?;
    tx.execute("DELETE FROM usergroups WHERE id = $1", &[&id]).await?;
    Ok(())
}

pub async fn delete_appearance_rows(tx: &Transaction<'_>, id: i32) -> WR<()> {
    tx.execute(
        "DELETE FROM layerappearances_properties WHERE appearance_id = $1",
        &[&id],
    )
    .await?;
    tx.execute("DELETE FROM layerappearances WHERE id = $1", &[&id]).await?;
    Ok(())
}

/// `LayerService.delete`: remove the layer from all maps that contain it
/// (the `@OrderColumn` list rows are renumbered like Hibernate does),
/// then remove the layer itself.
pub async fn delete_layer_rows(tx: &Transaction<'_>, id: i32) -> WR<()> {
    let maps: Vec<(i32, i32)> = tx
        .query(
            "SELECT map_id, idx FROM maps_layers WHERE layer_id = $1",
            &[&id],
        )
        .await?
        .iter()
        .map(|r| (r.get(0), r.get(1)))
        .collect();
    for (map_id, idx) in maps {
        tx.execute(
            "DELETE FROM maps_layers WHERE map_id = $1 AND idx = $2",
            &[&map_id, &idx],
        )
        .await?;
        let higher: Vec<i32> = tx
            .query(
                "SELECT idx FROM maps_layers WHERE map_id = $1 AND idx > $2 ORDER BY idx",
                &[&map_id, &idx],
            )
            .await?
            .iter()
            .map(|r| r.get(0))
            .collect();
        for j in higher {
            tx.execute(
                "UPDATE maps_layers SET idx = $1 WHERE map_id = $2 AND idx = $3",
                &[&(j - 1), &map_id, &j],
            )
            .await?;
        }
        // saveOrUpdate on the map module updates its modification time
        tx.execute("UPDATE modules SET modified = now() WHERE id = $1", &[&map_id]).await?;
    }
    tx.execute("DELETE FROM layers WHERE id = $1", &[&id]).await?;
    Ok(())
}

pub async fn delete_data_source_rows(tx: &Transaction<'_>, d: &LayerDataSource) -> WR<()> {
    let id = d.base.id.expect("loaded data source has an id");
    match d.kind() {
        DsKind::ImageWms => {
            tx.execute("DELETE FROM imagewmslayerdatasources WHERE id = $1", &[&id]).await?;
            tx.execute("DELETE FROM layerdatasources WHERE id = $1", &[&id]).await?;
        }
        DsKind::TileWms => {
            tx.execute("DELETE FROM tilewmslayerdatasources WHERE id = $1", &[&id]).await?;
            tx.execute("DELETE FROM imagewmslayerdatasources WHERE id = $1", &[&id]).await?;
            tx.execute("DELETE FROM layerdatasources WHERE id = $1", &[&id]).await?;
        }
        DsKind::Wfs => {
            tx.execute("DELETE FROM wfslayerdatasources WHERE id = $1", &[&id]).await?;
            tx.execute("DELETE FROM layerdatasources WHERE id = $1", &[&id]).await?;
        }
        DsKind::Wmts => {
            // @ManyToOne(cascade = CascadeType.ALL): the tile grid goes too
            let tg_id: Option<i32> = d
                .wmts
                .as_ref()
                .and_then(|w| w.tile_grid.as_ref())
                .and_then(|t| t.id);
            tx.execute(
                "DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1",
                &[&id],
            )
            .await?;
            tx.execute("DELETE FROM wmtslayerdatasources WHERE id = $1", &[&id]).await?;
            if let Some(tid) = tg_id {
                tx.execute(
                    "DELETE FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1",
                    &[&tid],
                )
                .await?;
                tx.execute(
                    "DELETE FROM tilegrid_resolution WHERE tilegrid_id = $1",
                    &[&tid],
                )
                .await?;
                tx.execute("DELETE FROM wmtstilegrids WHERE id = $1", &[&tid]).await?;
                tx.execute("DELETE FROM tilegrids WHERE id = $1", &[&tid]).await?;
            }
            tx.execute("DELETE FROM layerdatasources WHERE id = $1", &[&id]).await?;
        }
        DsKind::Xyz => {
            tx.execute(
                "DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1",
                &[&id],
            )
            .await?;
            tx.execute("DELETE FROM xyzlayerdatasources WHERE id = $1", &[&id]).await?;
            tx.execute("DELETE FROM layerdatasources WHERE id = $1", &[&id]).await?;
        }
    }
    Ok(())
}
