//! passwords, `ShogunCoreAuthenticationProvider` semantics) and the
//! entity permission evaluation (`ShogunCorePermissionEvaluator` with the
//! library's per-entity evaluators).

use crate::db::Pool;
use tokio_postgres::Client;

pub const SUPER_ADMIN_ROLE: &str = "ROLE_ADMIN";
pub const DEFAULT_USER_ROLE: &str = "ROLE_USER";

#[derive(Debug, Clone)]
pub struct AuthUser {
    pub id: i32,
    /// granted authorities: direct user roles plus all user group roles
    pub roles: Vec<String>,
}

impl AuthUser {
    pub fn has_role(&self, role: &str) -> bool {
        self.roles.iter().any(|r| r == role)
    }

    /// `RoleHierarchyImpl`: ROLE_ADMIN > ROLE_USER
    pub fn has_role_with_hierarchy(&self, role: &str) -> bool {
        if self.has_role(role) {
            return true;
        }
        if role == DEFAULT_USER_ROLE && self.has_role(SUPER_ADMIN_ROLE) {
            return true;
        }
        false
    }

    pub fn is_super_admin(&self) -> bool {
        self.has_role(SUPER_ADMIN_ROLE)
    }
}

/// Spring Security BCrypt pattern: `^\$2(a|y|b)?\$(\d\d)\$[./0-9A-Za-z]{53}$`
fn looks_like_bcrypt(hash: &str) -> bool {
    let b = hash.as_bytes();
    if b.len() != 60 {
        return false;
    }
    if b[0] != b'$' || b[1] != b'2' {
        return false;
    }
    match b[2] {
        b'a' | b'y' | b'b' => {
            if b[3] != b'$' {
                return false;
            }
        }
        b'$' => {}
        _ => return false,
    }
    // cost: two digits (only reached for the 2a/2y/2b form here)
    let cost_ok = b.len() > 5 && b[4].is_ascii_digit() && b[5].is_ascii_digit() && b[6] == b'$';
    if !cost_ok && b[3] == b'$' {
        return false;
    }
    if b[3] == b'$' {
        // $2$<cost>$<salt+hash>
        let rest = &b[7..];
        return rest.len() == 53 && rest.iter().all(|c| c.is_ascii_alphanumeric() || *c == b'.' || *c == b'/');
    }
    false
}

/// Decode a Basic authorization header value (already base64-decoded
/// credentials) the way Spring's `BasicAuthenticationFilter` does.
/// Returns `None` for anonymous users.
pub fn parse_basic(authorization: Option<&str>) -> Option<(String, String)> {
    let h = authorization?;
    let rest = h.strip_prefix("Basic ")?;
    // non-padded / garbage input: authentication failure (401)
    let decoded = base64_decode(rest.trim())?;
    let s = String::from_utf8(decoded).ok()?;
    let idx = s.find(':')?;
    Some((s[..idx].to_string(), s[idx + 1..].to_string()))
}

fn base64_decode(s: &str) -> Option<Vec<u8>> {
    let mut out = Vec::new();
    let mut acc: u32 = 0;
    let mut bits = 0;
    for c in s.chars() {
        if c == '=' {
            break;
        }
        let v = match c {
            'A'..='Z' => c as u32 - 'A' as u32,
            'a'..='z' => c as u32 - 'a' as u32 + 26,
            '0'..='9' => c as u32 - '0' as u32 + 52,
            '+' => 62,
            '/' => 63,
            _ => return None,
        };
        acc = (acc << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push(((acc >> bits) & 0xFF) as u8);
        }
    }
    Some(out)
}

/// `ShogunCoreAuthenticationProvider.authenticate`.
pub async fn authenticate(pool: &Pool, authz_header: Option<&str>) -> Option<AuthUser> {
    let (account, password) = parse_basic(authz_header)?;
    let client = pool.get().await.ok()?;
    let rows = client
        .query(
            "SELECT u.id, u.active, u.password FROM users u WHERE u.accountname = $1",
            &[&account],
        )
        .await
        .ok()?;
    let row = rows.first()?;
    let id: i32 = row.get(0);
    let active: bool = row.get(1);
    let hash: Option<String> = row.get(2);
    // inactive users cannot log in (DisabledException -> 401)
    if !active {
        return None;
    }
    let hash = hash.unwrap_or_default();
    // non-bcrypt stored passwords do not match (BCryptPasswordEncoder warns
    // and returns false)
    let ok = if hash.is_empty() || !looks_like_bcrypt(&hash) {
        false
    } else {
        bcrypt::verify(password.as_bytes(), &hash).unwrap_or(false)
    };
    if !ok {
        return None;
    }
    // direct roles and roles of all user groups
    let mut roles: Vec<String> = Vec::new();
    let direct: Vec<String> = client
        .query(
            "SELECT r.name FROM roles r JOIN users_roles ur ON ur.role_id = r.id WHERE ur.user_id = $1",
            &[&id],
        )
        .await
        .ok()?
        .iter()
        .map(|r| r.get(0))
        .collect();
    roles.extend(direct);
    let via_groups: Vec<String> = client
        .query(
            "SELECT DISTINCT r.name FROM roles r \
             JOIN usergroups_roles ugr ON ugr.role_id = r.id \
             JOIN user_usergroup uug ON uug.usergroup_id = ugr.usergroup_id \
             WHERE uug.user_id = $1",
            &[&id],
        )
        .await
        .ok()?
        .iter()
        .map(|r| r.get(0))
        .collect();
    for r in via_groups {
        if !roles.contains(&r) {
            roles.push(r);
        }
    }
    // a user without any authority is NOT authenticated (401)
    if roles.is_empty() {
        return None;
    }
    Some(AuthUser { id, roles })
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Permission {
    Admin,
    Create,
    Delete,
    Update,
    Read,
}

/// `EntityPermissionEvaluatorFactory` dispatch, expressed per REST resource.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum SecKind {
    User,
    UserGroup,
    Role,
    Layer,
    LayerDataSource,
    LayerAppearance,
}

/// `PersistentObjectPermissionEvaluator.hasPermission` on top of the
/// per-kind rules of the library's evaluators.
pub async fn has_permission(
    client: &Client,
    auth: &AuthUser,
    entity_id: i32,
    kind: SecKind,
    perm: Permission,
) -> Result<bool, tokio_postgres::Error> {
    // AlwaysAllowReadPermissionEvaluator types:
    if matches!(kind, SecKind::Role | SecKind::LayerDataSource | SecKind::LayerAppearance)
        && perm == Permission::Read
    {
        return Ok(true);
    }
    // UserPermissionEvaluator: READ is always granted on the own user object
    if kind == SecKind::User && perm == Permission::Read && auth.id == entity_id {
        return Ok(true);
    }
    // UserGroupPermissionEvaluator: READ for members
    if kind == SecKind::UserGroup && perm == Permission::Read {
        let rows = client
            .query(
                "SELECT 1 FROM user_usergroup WHERE user_id = $1 AND usergroup_id = $2",
                &[&auth.id, &entity_id],
            )
            .await?;
        if !rows.is_empty() {
            return Ok(true);
        }
    }
    // user permission collections on the entity
    let user_perms: Vec<String> = client
        .query(
            "SELECT pcp.permissions FROM userpermissions up \
             JOIN permissioncollections_permissions pcp ON pcp.permissioncollections_id = up.userpermissions_id \
             WHERE up.entity_id = $1 AND up.userpermissions_key = $2",
            &[&entity_id, &auth.id],
        )
        .await?
        .iter()
        .map(|r| r.get(0))
        .collect();
    if perms_grant(&user_perms, perm) {
        return Ok(true);
    }
    // group permission collections (aggregated over the user's groups)
    let group_ids: Vec<i32> = client
        .query(
            "SELECT usergroup_id FROM user_usergroup WHERE user_id = $1",
            &[&auth.id],
        )
        .await?
        .iter()
        .map(|r| r.get(0))
        .collect();
    if !group_ids.is_empty() {
        let group_perms: Vec<String> = client
            .query(
                "SELECT pcp.permissions FROM grouppermissions gp \
                 JOIN permissioncollections_permissions pcp ON pcp.permissioncollections_id = gp.grouppermissions_id \
                 WHERE gp.entity_id = $1 AND gp.grouppermissions_key = ANY($2)",
                &[&entity_id, &group_ids],
            )
            .await?
            .iter()
            .map(|r| r.get(0))
            .collect();
        if perms_grant(&group_perms, perm) {
            return Ok(true);
        }
    }
    Ok(false)
}

fn perms_grant(perms: &[String], perm: Permission) -> bool {
    let wanted = match perm {
        Permission::Admin => "ADMIN",
        Permission::Create => "CREATE",
        Permission::Delete => "DELETE",
        Permission::Update => "UPDATE",
        Permission::Read => "READ",
    };
