//! Jetty 9.4-style error pages, as the original's container produces for
//! Spring Security `sendError` responses.

pub fn page(status: u16, reason: &str, uri: &str) -> Vec<u8> {
    let title = format!("Error {} {}", status, reason);
    let mut out = String::new();
    out.push_str("<html>\n<head>\n");
    out.push_str("<meta http-equiv=\"Content-Type\" content=\"text/html;charset=utf-8\"/>\n");
    out.push_str(&format!("<title>{}</title>\n", title));
    out.push_str("</head>\n");
    out.push_str(&format!("<body><h2>HTTP ERROR {}</h2>\n", status));
    out.push_str(&format!("<p>Problem accessing {}. Reason:\n", uri));
    out.push_str(&format!("<pre>    {}</pre></p>", reason));
    out.push_str("<hr><a href=\"http://eclipse.org/jetty\">Powered by Jetty:// 9.4.8.v20171121</a><hr/>\n");
    out.push_str("\n</body>\n</html>\n");
    out.into_bytes()
}

/// The 500 page: like the plain error page plus a "Caused by" block with the
/// exception the original would have logged (Hibernate's
/// `InstantiationException` when the abstract `LayerDataSource` projection
/// tries to build an instance).
pub fn page_500(uri: &str, cause: &str) -> Vec<u8> {
    let title = "Error 500 Server Error";
    let mut out = String::new();
    out.push_str("<html>\n<head>\n");
    out.push_str("<meta http-equiv=\"Content-Type\" content=\"text/html;charset=utf-8\"/>\n");
    out.push_str(&format!("<title>{}</title>\n", title));
