//! SHOGun-Core REST slice, ported to Rust.
//!
//! Serves /rest/users, /rest/groups, /rest/roles, /rest/layers,
//! /rest/layerdatasources and /rest/layerappearances with the same HTTP
//! Basic authentication, permission model, status codes, JSON shapes,
//! `output:only` restriction, filters and database writes as the original
//! Java application, on the same PostgreSQL schema.

mod db;
mod de;
mod errorpage;
mod handlers;
mod httpd;
mod javaser;
mod json;
mod model;
mod repo;
mod security;

use handlers::Ctx;

fn main() {
    let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
        eprintln!("DATABASE_URL is not set");
        std::process::exit(1);
    });
    // normalize a postgresql:// prefix the same way the JDBC driver accepts
    // both spellings; tokio-postgres accepts postgres:// and postgresql://.
    let port: u16 = std::env::var("PORT").ok().and_then(|p| p.parse().ok()).unwrap_or(8080);

    let runtime = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .expect("tokio runtime");

    runtime.block_on(async move {
        // fail fast if the database is unreachable, with a short retry
        // window to tolerate a just-started PostgreSQL
        match db::Pool::connect_with_retry(&url, 20, 500).await {
            Ok(_) => {}
            Err(e) => {
                eprintln!("cannot connect to the database: {}", e);
                std::process::exit(1);
            }
        }
        let ctx = Ctx::new(&url);
        println!("shogun-core-rest listening on 0.0.0.0:{} (database: {})", port, url);
        if let Err(e) = httpd::serve(ctx, port).await {
            eprintln!("server error: {}", e);
            std::process::exit(1);
        }
    });
}

