        print("differs at", i)
        print("ref :", repr(a[max(0,i-100):i+200]))
        print("port:", repr(b[max(0,i-100):i+200]))
        break
else:
    print("prefix equal; lens", len(a), len(b))
    print("ref :", repr(a[len(b):][:300] if len(a)>len(b) else ""))
    print("port:", repr(b[len(a):][:300] if len(b)>len(a) else ""))
EOF

