//! Codec for the Java-serialization format that Hibernate uses to persist
//! element collections of `java.awt.geom.Point2D$Double` (the XYZ layer
//! datasource's `resolutions`) and, for rows created by hand,
//! `java.lang.Double`.

/// Stream magic + version: every row is an independent
/// `ObjectOutputStream` image.
const STREAM_HEADER: [u8; 4] = [0xAC, 0xED, 0x00, 0x05];

const TC_OBJECT: u8 = 0x73;
const TC_CLASSDESC: u8 = 0x72;
const TC_ENDBLOCKDATA: u8 = 0x78;
const TC_NULL: u8 = 0x70;
const TC_STRING: u8 = 0x74;

fn classdesc(name: &str, uid: [u8; 8], fields: &[(u8, &str)]) -> Vec<u8> {
    let mut out = Vec::new();
    out.push(TC_CLASSDESC);
    out.extend_from_slice(&(name.len() as u16).to_be_bytes());
    out.extend_from_slice(name.as_bytes());
    out.extend_from_slice(&uid);
    out.push(0x02); // java.io.Serializable
    out.extend_from_slice(&(fields.len() as u16).to_be_bytes());
    for (ty, fname) in fields {
        out.push(*ty);
        out.extend_from_slice(&(fname.len() as u16).to_be_bytes());
        out.extend_from_slice(fname.as_bytes());
    }
    out.push(TC_ENDBLOCKDATA);
    out.push(TC_NULL); // java.lang.Object superclass
    out
}

/// A deserialized element value.
#[derive(Debug, Clone, PartialEq)]
pub enum JavaValue {
    Null,
    Double(f64),
    Integer(i64),
    Str(String),
    Point2d(f64, f64),
}

/// Serialize a `java.awt.geom.Point2D$Double` exactly like `ObjectOutputStream`.
pub fn encode_point(x: f64, y: f64) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(&STREAM_HEADER);
    out.push(TC_OBJECT);
    out.extend_from_slice(&classdesc(
        "java.awt.geom.Point2D$Double",
        [0x55, 0x5B, 0xF8, 0xCA, 0x09, 0xA3, 0x1D, 0x5F],
        &[(b'D', "x"), (b'D', "y")],
    ));
    out.extend_from_slice(&x.to_bits().to_be_bytes());
    out.extend_from_slice(&y.to_bits().to_be_bytes());
    out
}

/// Serialize a `java.lang.Double`.
pub fn encode_double(d: f64) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(&STREAM_HEADER);
    out.push(TC_OBJECT);
    out.extend_from_slice(&classdesc(
        "java.lang.Double",
        [0x80, 0xB3, 0xC2, 0x4A, 0x29, 0x6B, 0xFB, 0x04],
        &[(b'D', "value")],
    ));
    out.extend_from_slice(&d.to_bits().to_be_bytes());
    out
}

/// `writeObject(null)`: a single TC_NULL byte.
pub fn encode_null() -> Vec<u8> {
    vec![TC_NULL]
}

fn double_classdesc_prefix() -> Vec<u8> {
    let mut v = STREAM_HEADER.to_vec();
    v.push(TC_OBJECT);
    v.extend_from_slice(&classdesc(
        "java.lang.Double",
        [0x80, 0xB3, 0xC2, 0x4A, 0x29, 0x6B, 0xFB, 0x04],
        &[(b'D', "value")],
    ));
    v
}

fn point_classdesc_prefix() -> Vec<u8> {
    let mut v = STREAM_HEADER.to_vec();
    v.push(TC_OBJECT);
    v.extend_from_slice(&classdesc(
        "java.awt.geom.Point2D$Double",
        [0x55, 0x5B, 0xF8, 0xCA, 0x09, 0xA3, 0x1D, 0x5F],
        &[(b'D', "x"), (b'D', "y")],
    ));
    v
}

/// Decode a persisted element. `Err(())` for bytes the original could not
/// deserialize either (its lazily loaded collection would fail with a
/// `StreamCorruptedException`, producing a 500).
pub fn decode_value(bytes: &[u8]) -> Result<JavaValue, ()> {
    if bytes == [TC_NULL] {
        return Ok(JavaValue::Null);
    }
    let dbl = double_classdesc_prefix();
    if bytes.len() == dbl.len() + 8 && bytes[..dbl.len()] == dbl[..] {
        let mut v = [0u8; 8];
        v.copy_from_slice(&bytes[dbl.len()..]);
        return Ok(JavaValue::Double(f64::from_bits(u64::from_be_bytes(v))));
    }
    let pnt = point_classdesc_prefix();
    if bytes.len() == pnt.len() + 16 && bytes[..pnt.len()] == pnt[..] {
        let mut vx = [0u8; 8];
        let mut vy = [0u8; 8];
        vx.copy_from_slice(&bytes[pnt.len()..pnt.len() + 8]);
        vy.copy_from_slice(&bytes[pnt.len() + 8..]);
        return Ok(JavaValue::Point2d(
            f64::from_bits(u64::from_be_bytes(vx)),
            f64::from_bits(u64::from_be_bytes(vy)),
        ));
    }
    // java.lang.Integer
    let int_prefix: Vec<u8> = {
        let mut v = STREAM_HEADER.to_vec();
        v.push(TC_OBJECT);
        v.extend_from_slice(&classdesc(
            "java.lang.Integer",
            [0x12, 0xE2, 0xA0, 0xA4, 0xF7, 0x81, 0x87, 0x38],
            &[(b'I', "value")],
        ));
        v
    };
    if bytes.len() == int_prefix.len() + 4 && bytes[..int_prefix.len()] == int_prefix[..] {
        let mut v = [0u8; 4];
        v.copy_from_slice(&bytes[int_prefix.len()..]);
        return Ok(JavaValue::Integer(i32::from_be_bytes(v) as i64));
    }
    // a plain String (TC_STRING + modified-UTF8)
    if bytes.len() >= 6 && bytes[0] == TC_STRING {
        if let Ok(len) = u16::from_be_bytes([bytes[1], bytes[2]]).map(|l| l as usize) {
            if bytes.len() == 3 + len {
                if let Ok(s) = std::str::from_utf8(&bytes[3..]) {
                    return Ok(JavaValue::Str(s.to_string()));
                }
            }
        }
    }
    Err(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn hex(s: &str) -> Vec<u8> {
        (0..s.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
            .collect()
    }

    #[test]
    fn point_roundtrip() {
        // captured from a real ObjectOutputStream run on Java 8:
        assert_eq!(
            encode_point(156543.03390625, 78271.516953125),
            hex("aced00057372001c6a6176612e6177742e67656f6d2e506f696e74324424446f75626c65555bf8ca09a31d5f0200024400017844000179787041031bf84570a3d740f31bf84570a3d7")
        );
        assert_eq!(encode_point(1.5, 0.0), hex("aced00057372001c6a6176612e6177742e67656f6d2e506f696e74324424446f75626c65555bf8ca09a31d5f020002440001784400017978703ff80000000000000000000000000000"));
        assert_eq!(
            decode_value(&encode_point(7.5, 8.5)).unwrap(),
            JavaValue::Point2d(7.5, 8.5)
        );
    }

    #[test]
    fn double_roundtrip() {
        assert_eq!(
            encode_double(1.5),
            hex("aced0005737200106a6176612e6c616e672e446f75626c6580b3c24a296bfb0402000144000576616c7565787200106a6176612e6c616e672e4e756d62657286ac951d0b94e08b02000078703ff8000000000000")
        );
        assert_eq!(decode_value(&encode_double(78271.516953125)).unwrap(), JavaValue::Double(78271.516953125));
        assert_eq!(decode_value(&encode_null()).unwrap(), JavaValue::Null);
        assert!(decode_value(b"garbage").is_err());
    }
}

