//! Integration tests for the ported REST slice.
//!
//! They run against the PostgreSQL database given by `DATABASE_URL` (the
//! environment provides one with `schema.sql` loaded and no data) and
//! exercise the request dispatcher end to end: authentication, the
//! permission evaluators, JSON shapes, `output:only` restriction, filters,
//! the id allocation from `hibernate_sequences` and the rows written.

use shogun_core_rest_lib as lib;

use lib::handlers::{route, Ctx, Req, Resp};
use std::time::Duration;

fn database_url() -> Option<String> {
    match std::env::var("DATABASE_URL") {
        Ok(u) if !u.is_empty() => Some(u),
        _ => None,
    }
}

async fn connect_or_skip(url: &str) -> Option<tokio_postgres::Client> {
    for _ in 0..20 {
        if let Ok(c) = lib::db::Pool::connect_raw(url).await {
            return Some(c);
        }
        tokio::time::sleep(Duration::from_millis(250)).await;
    }
    None
}

/// Ensure the schema exists; loads `schema.sql` (from the workspace root)
/// when the database is empty.
async fn ensure_schema(client: &tokio_postgres::Client) -> bool {
    let exists = client
        .query("SELECT 1 FROM information_schema.tables WHERE table_name = 'hibernate_sequences'", &[])
        .await
        .map(|r| !r.is_empty())
        .unwrap_or(false);
    if exists {
        return true;
    }
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../schema.sql");
    let sql = match std::fs::read_to_string(path) {
        Ok(s) => s,
        Err(_) => return false,
    };
    for stmt in sql.split(';') {
        let stmt: String = stmt
            .lines()
            .filter(|l| !l.trim_start().starts_with('\\') && !l.trim_start().starts_with("--"))
            .collect::<Vec<_>>()
            .join("\n");
        let stmt = stmt.trim();
        if stmt.is_empty() {
            continue;
        }
        if client.execute(stmt, &[]).await.is_err() {
            return false;
        }
    }
    true
}

fn req(method: &str, path: &str, auth: Option<(&str, &str)>, body: Option<&str>) -> Req {
    let mut r = Req::get(method, path);
    if let Some((u, p)) = auth {
        let creds = format!("{}:{}", u, p);
        const T: &[u8] =
            b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        let b = creds.as_bytes();
        let mut enc = String::new();
        for chunk in b.chunks(3) {
            let mut n = 0u32;
            for (i, x) in chunk.iter().enumerate() {
                n |= (*x as u32) << (16 - 8 * i);
            }
            let has = chunk.len();
            enc.push(T[((n >> 18) & 63) as usize] as char);
            enc.push(T[((n >> 12) & 63) as usize] as char);
            enc.push(if has > 1 { T[((n >> 6) & 63) as usize] as char } else { '=' });
            enc.push(if has > 2 { T[(n & 63) as usize] as char } else { '=' });
        }
        r.headers.push(("authorization".into(), format!("Basic {}", enc)));
    }
    if let Some(b) = body {
        r.body = b.as_bytes().to_vec();
    }
    if let Some(q) = path.split_once('?') {
        r.query = lib_parse_query(q.1);
    }
    r
}

fn lib_parse_query(q: &str) -> Vec<(String, String)> {
    let mut out = Vec::new();
    for part in q.split('&') {
        if part.is_empty() {
            continue;
        }
        let (k, v) = match part.split_once('=') {
            Some((k, v)) => (k, v),
            None => (part, ""),
        };
        out.push((lib::handlers::url_decode(k), lib::handlers::url_decode(v)));
    }
    out
}

async fn call(ctx: &Ctx, method: &str, path: &str, auth: Option<(&str, &str)>, body: Option<&str>) -> Resp {
    route(ctx, &req(method, path, auth, body)).await
}

fn body_str(r: &Resp) -> String {
    String::from_utf8_lossy(&r.body).into_owned()
}

macro_rules! assert_status {
    ($resp:expr, $status:expr, $what:expr) => {
        assert_eq!($resp.status, $status, "{}: status {} (body {})", $what, $resp.status, body_str(&$resp));
    };
}

/// The whole scenario in one test: the requests build on each other, so a
/// single linear flow keeps the database state manageable.
#[tokio::test]
async fn rest_slice_scenario() {
    let url = match database_url() {
        Some(u) => u,
        None => {
            eprintln!("DATABASE_URL not set; skipping integration scenario");
            return;
        }
    };
    let client = match connect_or_skip(&url).await {
        Some(c) => c,
        None => {
            eprintln!("database not reachable; skipping integration scenario");
            return;
        }
    };
    if !ensure_schema(&client).await {
        panic!("schema.sql tables are missing and could not be loaded");
    }

    // ---- fixtures ------------------------------------------------------
    // start from a clean slice state (the provided database has no data,
    // but repeated local runs may leave rows behind)
    let cleanup_sql = [
        "DELETE FROM xyzlayerdatasrc_resolution",
        "DELETE FROM wmtslayerdatasources_urls",
        "DELETE FROM wmtstilegrids_matrixids",
        "DELETE FROM tilegrid_resolution",
        "DELETE FROM tilewmslayerdatasources",
        "DELETE FROM wfslayerdatasources",
        "DELETE FROM wmtslayerdatasources",
        "DELETE FROM xyzlayerdatasources",
        "DELETE FROM imagewmslayerdatasources",
        "DELETE FROM layerdatasources",
        "DELETE FROM layerappearances_properties",
        "DELETE FROM layerappearances",
        "DELETE FROM layers",
        "DELETE FROM userpermissions",
        "DELETE FROM grouppermissions",
        "DELETE FROM permissioncollections_permissions",
        "DELETE FROM permissioncollections",
        "DELETE FROM users_roles",
        "DELETE FROM usergroups_roles",
        "DELETE FROM user_usergroup",
        "DELETE FROM usergroups",
        "DELETE FROM users",
        "DELETE FROM persons",
        "DELETE FROM roles",
        "DELETE FROM extents",
        "DELETE FROM tilegrids",
        "DELETE FROM wmtstilegrids",
        "DELETE FROM maps_layers",
        "DELETE FROM maps",
        "DELETE FROM modules",
    ];
    for s in cleanup_sql {
        let _ = client.execute(s, &[]).await;
    }
    let seq_before: i64 = client
        .query_one("SELECT COALESCE((SELECT next_val FROM hibernate_sequences WHERE sequence_name = 'default'), 0)", &[])
        .await
        .map(|r| r.get(0))
        .unwrap_or(0);
    // known starting point for the id allocation checks
    let _ = client
        .execute("INSERT INTO hibernate_sequences (sequence_name, next_val) VALUES ('default', 500) ON CONFLICT DO NOTHING", &[])
        .await;
    let _ = client
        .execute("UPDATE hibernate_sequences SET next_val = 500 WHERE sequence_name = 'default'", &[])
        .await;

    let pw_hash = bcrypt::hash("shogun", 10).unwrap();
    for (id, name, first, active) in [
        (201, "admin", "Admins first name", true),
        (202, "user", "Users first name", true),
        (203, "inactive", "Sleepy", false),
    ] {
        client
            .execute(
                "INSERT INTO persons (id, created, modified, firstname, lastname) VALUES ($1, now(), now(), $2, $3)",
                &[&id, &first, &format!("{} last name", first)],
            )
            .await
            .unwrap();
        client
            .execute(
                "INSERT INTO users (id, accountname, active, password) VALUES ($1, $2, $3, $4)",
                &[&id, &name, &active, &pw_hash],
            )
            .await
            .unwrap();
    }
    client
        .execute("INSERT INTO roles (id, created, modified, name, description) VALUES (210, now(), now(), 'ROLE_ADMIN', 'Administrator Role')", &[])
        .await
        .unwrap();
    client
        .execute("INSERT INTO roles (id, created, modified, name, description) VALUES (211, now(), now(), 'ROLE_USER', 'User Role')", &[])
        .await
        .unwrap();
    client.execute("INSERT INTO users_roles (user_id, role_id) VALUES (201, 210)", &[]).await.unwrap();
    client.execute("INSERT INTO users_roles (user_id, role_id) VALUES (202, 211)", &[]).await.unwrap();
    client
        .execute("INSERT INTO usergroups (id, created, modified, name, owner_id) VALUES (220, now(), now(), 'Admin User Group', 201)", &[])
        .await
        .unwrap();
    client
        .execute("INSERT INTO usergroups (id, created, modified, name, owner_id) VALUES (221, now(), now(), 'Default User Group', 201)", &[])
        .await
        .unwrap();
    client.execute("INSERT INTO user_usergroup (usergroup_id, user_id) VALUES (220, 201)", &[]).await.unwrap();
    client.execute("INSERT INTO user_usergroup (usergroup_id, user_id) VALUES (221, 202)", &[]).await.unwrap();
    client.execute("INSERT INTO usergroups_roles (usergroup_id, role_id) VALUES (220, 210)", &[]).await.unwrap();
    client.execute("INSERT INTO usergroups_roles (usergroup_id, role_id) VALUES (221, 211)", &[]).await.unwrap();

    let ctx = Ctx::new(&url);
    let admin = Some(("admin", "shogun"));
    let user = Some(("user", "shogun"));

    // ---- authentication ------------------------------------------------
    let r = call(&ctx, "GET", "/rest/users", None, None).await;
    assert_status!(r, 401, "unauthenticated request");
    assert!(r
        .headers
        .iter()
        .any(|(k, v)| k == "WWW-Authenticate" && v == "Basic realm=\"SHOGun Realm\""));

    let r = call(&ctx, "GET", "/rest/users", Some(("admin", "wrong")), None).await;
    assert_status!(r, 401, "wrong password");
    let r = call(&ctx, "GET", "/rest/users", Some(("nosuch", "x")), None).await;
    assert_status!(r, 401, "unknown account");
    let r = call(&ctx, "GET", "/rest/users", Some(("inactive", "shogun")), None).await;
    assert_status!(r, 401, "inactive user cannot log in");

    let r = call(&ctx, "GET", "/rest/users", admin, None).await;
    assert_status!(r, 200, "admin list");
    let b = body_str(&r);
    assert!(b.starts_with('[') && b.contains("\"accountName\":\"admin\""), "admin in list: {}", b);
    assert!(b.contains("\"accountName\":\"user\""), "user in list: {}", b);
    assert!(b.contains("\"userGroups\":[220]"), "group ids in user JSON: {}", b);
    assert!(b.contains("\"password\"") == false, "password is never serialized");

    // roles come as full objects
    let r = call(&ctx, "GET", "/rest/users/201", admin, None).await;
    assert_status!(r, 200, "get user by id");
    let b = body_str(&r);
    assert!(b.contains("\"roles\":[{\"id\":210,\"name\":\"ROLE_ADMIN\",\"description\":\"Administrator Role\"}]"), "{}", b);

    // a plain user only sees itself
    let r = call(&ctx, "GET", "/rest/users/201", user, None).await;
    assert_status!(r, 404, "other users are not readable");
    let r = call(&ctx, "GET", "/rest/users/202", user, None).await;
    assert_status!(r, 200, "own user object is readable");

    // groups: members may read, others not
    let r = call(&ctx, "GET", "/rest/groups/220", user, None).await;
    assert_status!(r, 404, "foreign group not readable");
    let r = call(&ctx, "GET", "/rest/groups/221", user, None).await;
    assert_status!(r, 200, "own group readable");

    // out-of-slice rest paths are admin-only
    let r = call(&ctx, "GET", "/rest/unknown", user, None).await;
    assert_status!(r, 403, "unknown /rest path requires ROLE_ADMIN");
    let r = call(&ctx, "GET", "/rest/unknown", admin, None).await;
    assert_status!(r, 404, "unknown /rest path has no handler");

    // ---- list / get for every resource ---------------------------------
    for path in ["/rest/roles", "/rest/groups", "/rest/layers", "/rest/layerdatasources", "/rest/layerappearances"] {
        let r = call(&ctx, "GET", path, admin, None).await;
        assert_status!(r, 200, "admin list {}", path);
        let r = call(&ctx, "GET", path, user, None).await;
        assert!(r.status == 200 || r.status == 404, "user list {}", path);
    }

    // ---- output:only ----------------------------------------------------
    let r = call(&ctx, "GET", "/rest/users?output:only=id,accountName", admin, None).await;
    assert_status!(r, 200, "restricted list");
    let b = body_str(&r);
    assert!(b.contains("\"firstName\":null"), "{}", b);
    assert!(b.contains("\"active\":false"), "primitive boolean default: {}", b);
    assert!(b.contains("\"roles\":[]"), "initialized empty collection: {}", b);

    // unknown restrict fields mean "no restriction"
    let r = call(&ctx, "GET", "/rest/users?output:only=doesnotexist", admin, None).await;
    assert_status!(r, 200, "unknown restrict field");
    assert!(body_str(&r).contains("\"firstName\":\"Admins first name\""));

    // ---- /filter --------------------------------------------------------
    let r = call(&ctx, "GET", "/rest/users/filter?accountName=user", admin, None).await;
    assert_status!(r, 200, "filter by accountName");
    let b = body_str(&r);
    assert!(b.contains("\"accountName\":\"user\"") && !b.contains("\"accountName\":\"admin\""), "{}", b);

    let r = call(&ctx, "GET", "/rest/users/filter", admin, None).await;
    assert_status!(r, 200, "filter without valid fields");
    assert_eq!(body_str(&r), "[]");

    let r = call(&ctx, "GET", "/rest/users/filter?active=maybe", admin, None).await;
    assert_status!(r, 200, "invalid boolean cast matches false");
    let r = call(&ctx, "GET", "/rest/users/filter?id=abc", admin, None).await;
    assert_status!(r, 200, "invalid int cast matches nothing");
    assert_eq!(body_str(&r), "[]");

    // case-insensitive field names, multiple values are ORed
    let r = call(&ctx, "GET", "/rest/roles/filter?NAME=ROLE_ADMIN&name=ROLE_USER", admin, None).await;
    assert_status!(r, 200, "filter multi value");
    let b = body_str(&r);
    assert!(b.contains("ROLE_ADMIN") && b.contains("ROLE_USER"), "{}", b);

    // ---- relations ------------------------------------------------------
    let r = call(&ctx, "GET", "/rest/users/201/userGroups", admin, None).await;
    assert_status!(r, 200, "user groups");
    let b = body_str(&r);
    assert!(b.contains("\"id\":220") && b.contains("\"name\":\"Admin User Group\""), "{}", b);

    // @PostFilter: a member only sees groups it may read
    let r = call(&ctx, "GET", "/rest/users/202/userGroups", user, None).await;
    assert_status!(r, 200, "own groups for plain user");
    assert!(body_str(&r).contains("\"id\":221"));

    let r = call(&ctx, "GET", "/rest/groups/221/users", user, None).await;
    assert_status!(r, 200, "group users");
    assert!(body_str(&r).contains("\"accountName\":\"user\""));

    let r = call(&ctx, "GET", "/rest/users/999/userGroups", admin, None).await;
    assert_status!(r, 404, "groups of missing user");

    // ---- create ---------------------------------------------------------
    let r = call(&ctx, "POST", "/rest/roles", user, Some(r#"{"name":"ROLE_X"}"#)).await;
    assert_status!(r, 400, "non-admin create denied");

    let r = call(&ctx, "POST", "/rest/roles", admin, Some(r#"{"id":1,"name":"ROLE_X"}"#)).await;
    assert_status!(r, 400, "create with id rejected");

    let r = call(&ctx, "POST", "/rest/roles", admin, Some(r#"{"name":"ROLE_TEST"}"#)).await;
    assert_status!(r, 201, "create role");
    let b = body_str(&r);
    assert!(b.contains("\"id\":501"), "id allocated from hibernate_sequences: {}", b);
    assert!(b.contains("\"name\":\"ROLE_TEST\""));

    // the sequence advanced to the new id
    let next: i64 = client
        .query_one("SELECT next_val FROM hibernate_sequences WHERE sequence_name = 'default'", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(next, 501);

    let r = call(&ctx, "POST", "/rest/roles", admin, Some(r#"{"name":"ROLE_TEST"}"#)).await;
    assert_status!(r, 400, "duplicate role name is a DB error");
    // ... and the failed create still consumed an id, like the original
    let next: i64 = client
        .query_one("SELECT next_val FROM hibernate_sequences WHERE sequence_name = 'default'", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(next, 502);

    let r = call(&ctx, "POST", "/rest/users", admin, Some(r#"{"firstName":"A","lastName":"B","accountName":"newu","password":"pw","active":true}"#)).await;
    assert_status!(r, 201, "create user");
    let b = body_str(&r);
    assert!(b.contains("\"id\":503"), "{}", b);
    assert!(b.contains("\"password\"") == false, "password never echoed");
    assert!(b.contains("\"active\":true") && b.contains("\"roles\":[]") && b.contains("\"userGroups\":[]"), "{}", b);
    // the password is stored verbatim (the original does not encrypt on this path)
    let stored: Option<String> = client
        .query_one("SELECT password FROM users WHERE accountname = 'newu'", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(stored.as_deref(), Some("pw"));

    // userGroups are resolved ids, roles need full objects
    let r = call(&ctx, "POST", "/rest/users", admin, Some(r#"{"accountName":"withgrp","active":true,"userGroups":[220],"roles":[{"id":211}]}"#)).await;
    assert_status!(r, 201, "create user with joins");
    let b = body_str(&r);
    assert!(b.contains("\"userGroups\":[220]") && b.contains("\"roles\":[{\"id\":211,\"name\":null,\"description\":null}]"), "{}", b);
    let in_group: i64 = client
        .query_one("SELECT count(*) FROM user_usergroup u JOIN users s ON s.id = u.user_id WHERE s.accountname = 'withgrp'", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(in_group, 1);

    let r = call(&ctx, "POST", "/rest/users", admin, Some(r#"{"accountName":"badgrp","active":true,"userGroups":[9999]}"#)).await;
    assert_status!(r, 400, "unresolvable group reference");

    // groups with a detached owner and members
    let r = call(&ctx, "POST", "/rest/groups", admin, Some(r#"{"name":"G2","owner":{"id":201},"members":[{"id":202}]}"#)).await;
    assert_status!(r, 201, "create group");
    let b = body_str(&r);
    assert!(b.contains("\"owner\":{\"id\":201"), "detached owner echoed as deserialized: {}", b);

    let r = call(&ctx, "POST", "/rest/groups", admin, Some(r#"{"name":"G3","owner":{"accountName":"x"}}"#)).await;
    assert_status!(r, 400, "transient owner is rejected");

    // layer appearances with properties
    let r = call(
        &ctx,
        "POST",
        "/rest/layerappearances",
        admin,
        Some(r#"{"name":"app","opacity":0.5,"visible":true,"properties":{"k1":"v1","k2":"2","k3":true,"k4":2.5}}"#),
    )
    .await;
    assert_status!(r, 201, "create appearance");
    let b = body_str(&r);
    assert!(b.contains("\"properties\":{\"k1\":\"v1\",\"k2\":\"2\",\"k3\":true,\"k4\":2.5}"), "{}", b);
    // the values are stored via toString and read back with best-matching types
    let rows: Vec<(String, String)> = client
        .query("SELECT property, value FROM layerappearances_properties a JOIN layerappearances s ON s.id = a.appearance_id WHERE s.name = 'app'", &[])
        .await
        .unwrap()
        .iter()
        .map(|r| (r.get(0), r.get(1)))
        .collect();
    assert!(rows.contains(&("k1".into(), "v1".into())));
    assert!(rows.contains(&("k3".into(), "true".into())));
    assert!(rows.contains(&("k4".into(), "2.5".into())));

    // layers: the abstract source cannot be built from JSON
    let r = call(&ctx, "POST", "/rest/layers", admin, Some(r#"{"name":"L1"}"#)).await;
    assert_status!(r, 201, "create layer without source");
    let r = call(&ctx, "POST", "/rest/layers", admin, Some(r#"{"name":"L2","source":{"id":1}}"#)).await;
    assert_status!(r, 400, "abstract source in create");
    let r = call(&ctx, "POST", "/rest/layerdatasources", admin, Some(r#"{"name":"x"}"#)).await;
    assert_status!(r, 400, "abstract data source create");

    // ---- update ---------------------------------------------------------
    let r = call(&ctx, "PUT", "/rest/users/202", admin, Some(r#"{"id":202,"firstName":"X"}"#)).await;
    assert_status!(r, 200, "partial update");
    assert!(body_str(&r).contains("\"firstName\":\"X\""));
    let first: String = client
        .query_one("SELECT firstname FROM persons WHERE id = 202", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(first, "X");

    let r = call(&ctx, "PUT", "/rest/users/202", admin, Some(r#"{"firstName":"Y"}"#)).await;
    assert_status!(r, 400, "missing id in body");
    let r = call(&ctx, "PUT", "/rest/users/202", admin, Some(r#"{"id":999,"firstName":"Y"}"#)).await;
    assert_status!(r, 400, "id mismatch");
    let r = call(&ctx, "PUT", "/rest/users/202", admin, Some("not json")).await;
    assert_status!(r, 404, "malformed json in update");
    let r = call(&ctx, "PUT", "/rest/users/202", admin, Some("")).await;
    assert_status!(r, 400, "empty body");
    let r = call(&ctx, "PUT", "/rest/users/999", admin, Some(r#"{"id":999,"firstName":"Z"}"#)).await;
    assert_status!(r, 404, "update of missing entity");

    // roles collections replace the join table
    let r = call(&ctx, "PUT", "/rest/users/202", admin, Some(r#"{"id":202,"roles":[{"id":210}],"userGroups":[220,221]}"#)).await;
    assert_status!(r, 200, "join replacement");
    let b = body_str(&r);
    assert!(b.contains("\"roles\":[{\"id\":210,\"name\":null,\"description\":null}]"), "deserialized role echoed: {}", b);
    assert!(b.contains("\"userGroups\":[220,221]"), "{}", b);
    let roles: i64 = client
        .query_one("SELECT count(*) FROM users_roles WHERE user_id = 202", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(roles, 1);
    let groups: i64 = client
        .query_one("SELECT count(*) FROM user_usergroup WHERE user_id = 202", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(groups, 2);
    // the join tables are also written when userGroups is absent (kept)
    let r = call(&ctx, "PUT", "/rest/users/202", admin, Some(r#"{"id":202,"firstName":"W"}"#)).await;
    assert_status!(r, 200, "untouched collections keep their rows");
    let groups: i64 = client
        .query_one("SELECT count(*) FROM user_usergroup WHERE user_id = 202", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(groups, 2);

    // json null clears the join tables and is echoed as null
    let r = call(&ctx, "PUT", "/rest/users/202", admin, Some(r#"{"id":202,"roles":null}"#)).await;
    assert_status!(r, 200, "null collection");
    assert!(body_str(&r).contains("\"roles\":null"));
    let roles: i64 = client
        .query_one("SELECT count(*) FROM users_roles WHERE user_id = 202", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(roles, 0);

    // unknown fields are 404s, but the fields before them are flushed
    let r = call(&ctx, "PUT", "/rest/users/202", admin, Some(r#"{"id":202,"lastName":"Flushed","unknownField":1}"#)).await;
    assert_status!(r, 404, "unknown field in update");
    let last: String = client
        .query_one("SELECT lastname FROM persons WHERE id = 202", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(last, "Flushed", "OpenSessionInView flush of the partial update");

    // id mismatch is checked before anything is deserialized
    let r = call(&ctx, "PUT", "/rest/users/202", admin, Some(r#"{"id":999,"firstName":"Never"}"#)).await;
    assert_status!(r, 400, "id mismatch before deserialization");
    let first: String = client
        .query_one("SELECT firstname FROM persons WHERE id = 202", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(first, "W");

    // ---- permission collections ----------------------------------------
    // grant the plain user UPDATE and DELETE on one of the roles
    client
        .execute("INSERT INTO permissioncollections (id, created, modified) VALUES (230, now(), now())", &[])
        .await
        .unwrap();
    for p in ["READ", "UPDATE", "DELETE"] {
        client
            .execute("INSERT INTO permissioncollections_permissions (permissioncollections_id, permissions) VALUES (230, $1)", &[&p])
            .await
            .unwrap();
    }
    client
        .execute("INSERT INTO userpermissions (entity_id, userpermissions_id, userpermissions_key) VALUES (210, 230, 202)", &[])
        .await
        .unwrap();
    // ... and group permissions for the user's group on the other role
    client
        .execute("INSERT INTO permissioncollections (id, created, modified) VALUES (231, now(), now())", &[])
        .await
        .unwrap();
    client
        .execute("INSERT INTO permissioncollections_permissions (permissioncollections_id, permissions) VALUES (231, 'ADMIN')", &[])
        .await
        .unwrap();
    client
        .execute("INSERT INTO grouppermissions (entity_id, grouppermissions_id, grouppermissions_key) VALUES (211, 231, 221)", &[])
        .await
        .unwrap();

    let r = call(&ctx, "PUT", "/rest/roles/210", user, Some(r#"{"id":210,"description":"d"}"#)).await;
    assert_status!(r, 200, "granted UPDATE via user permission collection");
    let r = call(&ctx, "DELETE", "/rest/roles/210", user, None).await;
    assert_status!(r, 204, "granted DELETE via user permission collection");
    // ... but the delete fails on the users_roles FK of the admin
    let gone: i64 = client
        .query_one("SELECT count(*) FROM roles WHERE id = 210", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(gone, 1, "FK violation rolled the delete back");

    // ADMIN permission via the group grants everything
    let r = call(&ctx, "PUT", "/rest/roles/211", user, Some(r#"{"id":211,"description":"gd"}"#)).await;
    assert_status!(r, 200, "group ADMIN permission");
    let d: Option<String> = client
        .query_one("SELECT description FROM roles WHERE id = 211", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(d.as_deref(), Some("gd"));

    // ---- delete ---------------------------------------------------------
    let r = call(&ctx, "DELETE", "/rest/users/202", user, None).await;
    assert_status!(r, 404, "delete without DELETE permission");
    // via the user permission collection on role 210 the delete passed the
    // permission check but failed on the FK; now remove the FK first
    client.execute("DELETE FROM users_roles WHERE user_id = 201", &[]).await.unwrap();
    client.execute("DELETE FROM usergroups_roles WHERE role_id = 210", &[]).await.unwrap();
    let r = call(&ctx, "DELETE", "/rest/roles/210", admin, None).await;
    assert_status!(r, 204, "delete role");
    let gone: i64 = client
        .query_one("SELECT count(*) FROM roles WHERE id = 210", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(gone, 0);

    // ---- layer data source subtypes ------------------------------------
    // (created directly in the database, like the original's demo content)
    client
        .execute(
            "INSERT INTO extents (id, created, modified, lowerleft_x, lowerleft_y, upperright_x, upperright_y) VALUES (240, now(), now(), -100.5, -50.25, 100.5, 50.25)",
            &[],
        )
        .await
        .unwrap();
    client
        .execute(
            "INSERT INTO tilegrids (id, created, modified, tilegridorigin_x, tilegridorigin_y, tilesize, type, tilegridextent_id) VALUES (241, now(), now(), 0.0, 0.0, 256, 'TileGrid', 240)",
            &[],
        )
        .await
        .unwrap();
    for (i, res) in [156543.03390625, 78271.516953125, 1.5].iter().enumerate() {
        client
            .execute(
                "INSERT INTO tilegrid_resolution (tilegrid_id, resolution, idx) VALUES (241, $1, $2)",
                &[res, &(i as i32)],
            )
            .await
            .unwrap();
    }
    client
        .execute(
            "INSERT INTO layerdatasources (id, created, modified, name, type, url) VALUES (250, now(), now(), null, 'TileWMS', 'http://ows/example?')",
            &[],
        )
        .await
        .unwrap();
    client
        .execute(
            "INSERT INTO imagewmslayerdatasources (height, layernames, layerstyles, version, width, id) VALUES (256, 'OSM-WMS', '', '1.1.0', 256, 250)",
            &[],
        )
        .await
        .unwrap();
    client
        .execute(
            "INSERT INTO tilewmslayerdatasources (request_with_tiled, id, tilegrid_id) VALUES (true, 250, 241)",
            &[],
        )
        .await
        .unwrap();
    client
        .execute(
            "INSERT INTO layers (id, created, modified, name, source_id) VALUES (260, now(), now(), 'OSM-WMS', 250)",
            &[],
        )
        .await
        .unwrap();

    let r = call(&ctx, "GET", "/rest/layerdatasources/250", user, None).await;
    assert_status!(r, 200, "data sources are readable by everyone");
    let b = body_str(&r);
    assert!(
        b.contains("\"tileGrid\":{\"id\":241") && b.contains("\"tileGridResolutions\":[156543.03390625,78271.516953125,1.5]"),
        "{}",
        b
    );
    assert!(b.contains("\"x\":0.0,\"y\":0.0"), "Java double formatting: {}", b);
    assert!(b.contains("\"lowerLeft\":{\"x\":-100.5,\"y\":-50.25}"), "{}", b);

    // updating fields of a concrete subtype works; the tile grid is a
    // cascade-save-update association
    let r = call(
        &ctx,
        "PUT",
        "/rest/layerdatasources/250",
        admin,
        Some(r#"{"id":250,"url":"http://new","layerNames":"a,b"}"#),
    )
    .await;
    assert_status!(r, 200, "update tile wms fields");
    let b = body_str(&r);
    assert!(b.contains("\"url\":\"http://new\"") && b.contains("\"layerNames\":\"a,b\""), "{}", b);

    // a detached tile grid with the session id fails (NonUniqueObjectException)
    let r = call(&ctx, "PUT", "/rest/layerdatasources/250", admin, Some(r#"{"id":250,"tileGrid":{"id":241}}"#)).await;
    assert_status!(r, 404, "tile grid conflict");

    // a fully deserialized tile grid is cascaded as a NEW instance
    let r = call(
        &ctx,
        "PUT",
        "/rest/layerdatasources/250",
        admin,
        Some(r#"{"id":250,"tileGrid":{"type":"TileGrid","tileGridOrigin":{"x":1.5,"y":2.5},"tileSize":512,"tileGridResolutions":[7.5,8.5]}}"#),
    )
    .await;
    assert_status!(r, 200, "cascaded new tile grid");
    let b = body_str(&r);
    assert!(b.contains("\"tileSize\":512"), "constructor default applied: {}", b);
    let new_id: i32 = {
        let s = b.split("\"tileGrid\":{\"id\":").nth(1).unwrap();
        s.split(',').next().unwrap().parse().unwrap()
    };
    let res: i64 = client
        .query_one("SELECT count(*) FROM tilegrid_resolution WHERE tilegrid_id = $1", &[&new_id])
        .await
        .unwrap()
        .get(0);
    assert_eq!(res, 2);
    // the old tile grid keeps its rows
    let old_res: i64 = client
        .query_one("SELECT count(*) FROM tilegrid_resolution WHERE tilegrid_id = 241", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(old_res, 3);

    // ---- XYZ resolutions (Java-serialized Point2D.Double) --------------
    client
        .execute(
            "INSERT INTO layerdatasources (id, created, modified, name, type, url) VALUES (251, now(), now(), null, 'XYZ', 'http://xyz')",
            &[],
        )
        .await
        .unwrap();
    client
        .execute(
            "INSERT INTO xyzlayerdatasources (center_x, center_y, tilesize, id, extent_id) VALUES (9.5, 8.5, 256, 251, 240)",
            &[],
        )
        .await
        .unwrap();
    let point_bytes = lib::javaser::encode_point(156543.03390625, 78271.516953125);
    client
        .execute(
            "INSERT INTO xyzlayerdatasrc_resolution (xyzlayerdatasrc_id, resolution, idx) VALUES (251, $1, 0)",
            &[&point_bytes],
        )
        .await
        .unwrap();

    let r = call(&ctx, "GET", "/rest/layerdatasources/251", admin, None).await;
    assert_status!(r, 200, "xyz read");
    let b = body_str(&r);
    assert!(b.contains("\"resolutions\":[{\"x\":156543.03390625,\"y\":78271.516953125}]"), "{}", b);

    // numbers cannot be deserialized into Point2D: the whole PUT fails
    let r = call(&ctx, "PUT", "/rest/layerdatasources/251", admin, Some(r#"{"id":251,"resolutions":[1.5]}"#)).await;
    assert_status!(r, 404, "resolutions as numbers fail");
    // ... but {x,y} objects are written as Java-serialized points
    let r = call(
        &ctx,
        "PUT",
        "/rest/layerdatasources/251",
        admin,
        Some(r#"{"id":251,"resolutions":[{"x":1.5,"y":2.5},{"x":3.25}],"tileSize":512}"#),
    )
    .await;
    assert_status!(r, 200, "resolutions as points");
    let stored: Vec<Vec<u8>> = client
        .query("SELECT resolution FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = 251 ORDER BY idx", &[])
        .await
        .unwrap()
        .iter()
        .map(|r| r.get(0))
        .collect();
    assert_eq!(stored.len(), 2);
    assert_eq!(lib::javaser::decode_value(&stored[0]).unwrap(), lib::javaser::JavaValue::Point2d(1.5, 2.5));
    assert_eq!(lib::javaser::decode_value(&stored[1]).unwrap(), lib::javaser::JavaValue::Point2d(3.25, 0.0));

    // ---- layer cascade (appearance) ------------------------------------
    let r = call(&ctx, "PUT", "/rest/layers/260", admin, Some(r#"{"id":260,"source":null}"#)).await;
    assert_status!(r, 200, "clear layer source");
    let r = call(&ctx, "PUT", "/rest/layers/260", admin, Some(r#"{"id":260,"source":{"id":250}}"#)).await;
    assert_status!(r, 404, "abstract source in update");

    let r = call(&ctx, "POST", "/rest/layers", admin, Some(r#"{"name":"L9","appearance":{"name":"App9","opacity":0.9}}"#)).await;
    assert_status!(r, 201, "layer with cascaded appearance");
    let b = body_str(&r);
    assert!(b.contains("\"appearance\":{\"id\":"), "{}", b);
    let app_id: i32 = {
        let s = b.split("\"appearance\":{\"id\":").nth(1).unwrap();
        s.split(',').next().unwrap().parse().unwrap()
    };
    let name: Option<String> = client
        .query_one("SELECT name FROM layerappearances WHERE id = $1", &[&app_id])
        .await
        .unwrap()
        .get(0);
    assert_eq!(name.as_deref(), Some("App9"));

    // ---- output:only on the abstract projection is a 500 ---------------
    let r = call(&ctx, "GET", "/rest/layerdatasources?output:only=name", admin, None).await;
    assert_status!(r, 500, "aliasToBean cannot instantiate the abstract class");
    assert!(body_str(&r).contains("HTTP ERROR 500"));

    // ---- method routing -------------------------------------------------
    let r = call(&ctx, "PATCH", "/rest/users", admin, None).await;
    assert_status!(r, 405, "PATCH not allowed");
    assert!(r.headers.iter().any(|(k, v)| k == "Allow" && v == "GET, POST"));
    let r = call(&ctx, "GET", "/rest/users/abc", admin, None).await;
    assert_status!(r, 400, "non-integer path variable");
    let r = call(&ctx, "GET", "/rest/users/1/xyz", admin, None).await;
    assert_status!(r, 404, "unknown sub path");
    let r = call(&ctx, "GET", "/rest/users/", admin, None).await;
    assert_status!(r, 200, "trailing slash matches the collection");

    // ---- cleanup --------------------------------------------------------
    for s in cleanup_sql {
        let _ = client.execute(s, &[]).await;
    }
    // restore the sequence row as we found it
    let _ = client
        .execute("DELETE FROM hibernate_sequences WHERE sequence_name = 'default'", &[])
        .await;
    if seq_before > 0 {
        let _ = client
            .execute("INSERT INTO hibernate_sequences (sequence_name, next_val) VALUES ('default', $1)", &[&seq_before])
            .await;
    }
}

